insert into public.therapist_resources (slug, title, kind, summary, goal, audience, duration, body_md, fields, tags, created_at)
values
  ('weekly-values-compass-check-in-page', 'Weekly Values Compass Check-In Page', 'worksheet'::resource_kind, 'A one-page weekly look at which values a client moved toward and which got set aside.', 'Use it to help a client notice whether the week matched what matters to them.', array['Adults']::text[], '15 minutes weekly', 'Keep the compass simple: three values at most. Clients often list values they think they should hold, so ask which ones they would stand behind even if nobody knew. Review it together and let the client choose one small adjustment.', '[{"id": "f0", "type": "textarea", "label": "The three values I want to steer by this week:"}, {"id": "f1", "type": "textarea", "label": "One thing I did that moved me toward a value:"}, {"id": "f2", "type": "textarea", "label": "One place I drifted, and what pulled me off course:"}, {"id": "f3", "type": "textarea", "label": "One small adjustment for next week:"}]'::jsonb, array['values', 'weekly review', 'direction']::text[], '2026-10-31T15:00:00+00:00'::timestamptz),
  ('two-minute-decision-pause-sheet', 'Two-Minute Decision Pause Sheet', 'worksheet'::resource_kind, 'A short sheet for stopping before a choice and naming the options, the pull and the next step.', 'Use it to help a client slow down a decision long enough to choose on purpose.', array['Adults']::text[], '10 minutes', 'Walk through one real, low-stakes decision in session first. Notice whether the client rushes toward relief or stalls for certainty, and name which one you see without judging it. The sheet is a prompt for their thinking, not a verdict.', '[{"id": "f0", "type": "textarea", "label": "The decision in front of me:"}, {"id": "f1", "type": "textarea", "label": "Two or three options I can see:"}, {"id": "f2", "type": "textarea", "label": "What each option is protecting or costing me:"}, {"id": "f3", "type": "textarea", "label": "The next small step I will take, and when:"}]'::jsonb, array['decision making', 'pause', 'planning']::text[], '2026-10-31T15:00:00+00:00'::timestamptz),
  ('strengths-in-action-evidence-page', 'Strengths in Action Evidence Page', 'worksheet'::resource_kind, 'A page where a client collects recent moments that show a strength at work.', 'Use it to help a client see their own strengths in everyday moments.', array['Adults', 'Teens']::text[], '15 minutes', 'Clients who discount compliments often do better with their own observations. Ask for small, concrete moments rather than big wins, and have them say what the moment shows about them. Add to the page across sessions.', '[{"id": "f0", "type": "textarea", "label": "A strength I want to look for this week:"}, {"id": "f1", "type": "textarea", "label": "A moment I used it, even a small one:"}, {"id": "f2", "type": "textarea", "label": "What that moment shows about me:"}, {"id": "f3", "type": "textarea", "label": "Where I could use it again soon:"}]'::jsonb, array['strengths', 'evidence log', 'self-worth']::text[], '2026-10-31T15:00:00+00:00'::timestamptz),
  ('boundary-script-builder-worksheet', 'Boundary Script Builder Worksheet', 'worksheet'::resource_kind, 'A fill-in page for drafting a short, kind and firm sentence for a boundary a client wants to set.', 'Use it to help a client put a boundary into words before the conversation.', array['Adults']::text[], '20 minutes', 'Pick one specific boundary with one person. Draft the sentence together, then say it aloud so the client hears it in their own voice. Expect guilt and talk it through; the script is theirs to edit and the choice to use it is theirs too.', '[{"id": "f0", "type": "textarea", "label": "The situation where I need a boundary:"}, {"id": "f1", "type": "textarea", "label": "What I need, in one clear sentence:"}, {"id": "f2", "type": "textarea", "label": "What I might say if the other person pushes back:"}, {"id": "f3", "type": "textarea", "label": "How I will care for myself afterward:"}]'::jsonb, array['boundaries', 'assertiveness', 'scripts']::text[], '2026-10-31T15:00:00+00:00'::timestamptz),
  ('spend-and-refill-energy-weekly-planner', 'Spend and Refill Energy Weekly Planner', 'worksheet'::resource_kind, 'A planner that treats energy like a budget of spending and refilling across the week.', 'Use it to help a client spread demands and rest more evenly across a week.', array['Adults']::text[], '20 minutes', 'Have the client rate how draining and how restoring things are for them, not what they think should be. Look for days with all spending and no refilling. Start with one swap, not a full rebuild of the week.', '[{"id": "f0", "type": "textarea", "label": "Things that spend a lot of my energy:"}, {"id": "f1", "type": "textarea", "label": "Things that refill it:"}, {"id": "f2", "type": "textarea", "label": "The day this week with the least refill:"}, {"id": "f3", "type": "textarea", "label": "One swap I will try:"}]'::jsonb, array['energy', 'planning', 'balance']::text[], '2026-10-31T15:00:00+00:00'::timestamptz),
  ('thought-detective-clue-sheet', 'Thought Detective Clue Sheet', 'cbt'::resource_kind, 'A clue-gathering sheet for treating a thought as a lead to check rather than a fact.', 'Use it to help a client look for evidence for and against a distressing thought.', array['Adults', 'Teens']::text[], '20 minutes', 'Keep the tone curious, like a detective who has not decided the answer. Ask for facts a stranger could verify and mark which clues are feelings. Finish with a more balanced statement the client believes, not one they think they should.', '[{"id": "f0", "type": "textarea", "label": "The thought I am investigating:"}, {"id": "f1", "type": "textarea", "label": "Clues that point toward it being true:"}, {"id": "f2", "type": "textarea", "label": "Clues that point away from it:"}, {"id": "f3", "type": "textarea", "label": "A fair statement that fits all the clues:"}]'::jsonb, array['thought challenging', 'evidence', 'balanced thinking']::text[], '2026-10-31T15:00:00+00:00'::timestamptz),
  ('other-ways-to-read-it-brainstorm-page', 'Other Ways to Read It Brainstorm Page', 'cbt'::resource_kind, 'A page for listing several other ways to read a situation before settling on one.', 'Use it to help a client loosen a single rigid interpretation of an event.', array['Adults', 'Teens']::text[], '15 minutes', 'Choose an event where the client jumped to one reading. Aim for quantity first, even silly explanations, then rank them by how well they fit the facts. The point is flexibility, not forcing a positive spin.', '[{"id": "f0", "type": "textarea", "label": "What happened, only the facts:"}, {"id": "f1", "type": "textarea", "label": "The explanation my mind jumped to:"}, {"id": "f2", "type": "textarea", "label": "Three other explanations that could fit:"}, {"id": "f3", "type": "textarea", "label": "How I could find out which fits best:"}]'::jsonb, array['interpretation', 'cognitive flexibility', 'assumptions']::text[], '2026-10-31T15:00:00+00:00'::timestamptz),
  ('behavior-and-mood-before-and-after-log', 'Behavior and Mood Before and After Log', 'cbt'::resource_kind, 'A log pairing an activity with mood ratings from before and after it.', 'Use it to help a client see how what they do shifts how they feel.', array['Adults']::text[], 'One week', 'Have the client rate mood from zero to ten before and after each entry. Expect surprises in both directions, and treat them as information. Review for patterns in session before suggesting any change.', '[{"id": "f0", "type": "textarea", "label": "The activity:"}, {"id": "f1", "type": "textarea", "label": "My mood before, zero to ten:"}, {"id": "f2", "type": "textarea", "label": "My mood after, zero to ten:"}, {"id": "f3", "type": "textarea", "label": "What I notice across this week:"}]'::jsonb, array['behavioral', 'mood tracking', 'log']::text[], '2026-10-31T15:00:00+00:00'::timestamptz),
  ('should-statement-softening-page', 'Should Statement Softening Page', 'cbt'::resource_kind, 'A page for turning rigid shoulds and musts into flexible preferences.', 'Use it to help a client notice the pressure in should thinking and try gentler wording.', array['Adults']::text[], '15 minutes', 'Ask the client to collect the shoulds they say to themselves in a day. Rewrite one together as a preference or a choice, and note how the feeling changes. Avoid arguing about whether the rule is right; just test the wording.', '[{"id": "f0", "type": "textarea", "label": "A should I told myself today:"}, {"id": "f1", "type": "textarea", "label": "Where I learned this rule:"}, {"id": "f2", "type": "textarea", "label": "How it feels to follow it, and to bend it:"}, {"id": "f3", "type": "textarea", "label": "A softer version I could live with:"}]'::jsonb, array['cognitive distortions', 'self-talk', 'standards']::text[], '2026-10-31T15:00:00+00:00'::timestamptz),
  ('cost-of-a-belief-three-column-page', 'Cost of a Belief Three-Column Page', 'cbt'::resource_kind, 'A three-column page weighing what a belief gives a client and what it costs them.', 'Use it to help a client consider whether a long-held belief is still serving them.', array['Adults']::text[], '25 minutes', 'Do not ask the client to drop the belief. Fill the benefits column first so they feel heard, then costs. Many clients choose to keep part of it and reshape the rest, which is a fine outcome.', '[{"id": "f0", "type": "textarea", "label": "The belief I hold:"}, {"id": "f1", "type": "textarea", "label": "What it gives me:"}, {"id": "f2", "type": "textarea", "label": "What it costs me:"}, {"id": "f3", "type": "textarea", "label": "A version of it I could try on this week:"}]'::jsonb, array['core beliefs', 'cost-benefit', 'belief change']::text[], '2026-10-31T15:00:00+00:00'::timestamptz),
  ('values-birthday-speech-page', 'Values Birthday Speech Page', 'act'::resource_kind, 'A page where a client imagines what people close to them would say they stood for.', 'Use it to help a client name values by imagining how they want to be known.', array['Adults']::text[], '25 minutes', 'This can stir up grief or self-criticism, so go slowly and let the client choose how much to write. Listen for the words that repeat and turn them into values. Close with one action this week that matches them.', '[{"id": "f0", "type": "textarea", "label": "Three people I would want to hear from:"}, {"id": "f1", "type": "textarea", "label": "What I hope each would say about how I treated them:"}, {"id": "f2", "type": "textarea", "label": "Words that keep coming up:"}, {"id": "f3", "type": "textarea", "label": "One action this week that fits those words:"}]'::jsonb, array['values', 'meaning', 'committed action']::text[], '2026-10-31T15:00:00+00:00'::timestamptz),
  ('clouds-in-the-sky-observer-page', 'Clouds in the Sky Observer Page', 'act'::resource_kind, 'A practice page for watching thoughts drift by like clouds without chasing them.', 'Use it to help a client practice noticing thoughts from a step back.', array['Adults']::text[], 'Ten minutes', 'Do it together for two minutes first. Clients often judge themselves for getting hooked; remind them that noticing the hook is the practice. Note which thoughts hook hardest and bring those back to the next session.', '[{"id": "f0", "type": "textarea", "label": "Thoughts I noticed floating by:"}, {"id": "f1", "type": "textarea", "label": "The one that was hardest to let drift:"}, {"id": "f2", "type": "textarea", "label": "What I did when I got pulled in:"}, {"id": "f3", "type": "textarea", "label": "How I will come back to it again:"}]'::jsonb, array['defusion', 'observing self', 'present moment']::text[], '2026-10-31T15:00:00+00:00'::timestamptz),
  ('unhooked-moment-capture-log', 'Unhooked Moment Capture Log', 'act'::resource_kind, 'A log for recording moments when a client noticed being hooked and stepped back.', 'Use it to help a client build awareness of getting hooked and unhooking.', array['Adults']::text[], 'One week', 'Celebrate noticing, not winning. Ask what the hook was, what it pulled them toward and what they did instead, however small. Look for places where values gave them somewhere to go.', '[{"id": "f0", "type": "textarea", "label": "The moment I got hooked:"}, {"id": "f1", "type": "textarea", "label": "What my mind was telling me:"}, {"id": "f2", "type": "textarea", "label": "What I did once I noticed:"}, {"id": "f3", "type": "textarea", "label": "What I was moving toward instead:"}]'::jsonb, array['cognitive fusion', 'awareness', 'log']::text[], '2026-10-31T15:00:00+00:00'::timestamptz),
  ('small-committed-step-contract', 'Small Committed Step Contract', 'act'::resource_kind, 'A one-page agreement a client makes with themselves for a tiny values-based action.', 'Use it to help a client turn a value into a concrete step they can name and schedule.', array['Adults']::text[], '15 minutes', 'Make the step small enough that the client rates their confidence at eight or above. Ask what discomfort might show up and what they are willing to carry with them. Check in next session without scoring it.', '[{"id": "f0", "type": "textarea", "label": "The value behind this step:"}, {"id": "f1", "type": "textarea", "label": "The step, with a day and time:"}, {"id": "f2", "type": "textarea", "label": "The uncomfortable feelings I am willing to bring along:"}, {"id": "f3", "type": "textarea", "label": "Who or what could help me follow through:"}]'::jsonb, array['committed action', 'willingness', 'small steps']::text[], '2026-10-31T15:00:00+00:00'::timestamptz),
  ('hands-as-thoughts-defusion-page', 'Hands as Thoughts Defusion Page', 'act'::resource_kind, 'A page built around holding thoughts up to the face, then at arm length, and what changes.', 'Use it to help a client feel the difference between being fused with a thought and holding it.', array['Adults']::text[], 'Ten minutes', 'Have the client hold their hands tight against their face and describe the view, then lower them to the lap. It is a physical metaphor, so let them find their own words. Ask what they could do with their hands free.', '[{"id": "f0", "type": "textarea", "label": "What I could and could not see with my hands on my face:"}, {"id": "f1", "type": "textarea", "label": "What changed when I moved them away:"}, {"id": "f2", "type": "textarea", "label": "A thought I want to hold at arm length this week:"}, {"id": "f3", "type": "textarea", "label": "What my free hands could be doing:"}]'::jsonb, array['defusion', 'metaphor', 'experiential']::text[], '2026-10-31T15:00:00+00:00'::timestamptz),
  ('wise-mind-pause-practice-page', 'Wise Mind Pause Practice Page', 'dbt'::resource_kind, 'A page for checking in with emotion mind, reasonable mind and wise mind before acting.', 'Use it to help a client find a pause where wise mind can join a decision.', array['Adults', 'Teens']::text[], '15 minutes', 'Let the client describe each mind in their own words with a recent example. Practice finding wise mind together with a slow breath and a question. Do not expect a perfect answer; the goal is a pause.', '[{"id": "f0", "type": "textarea", "label": "A moment I acted from emotion mind:"}, {"id": "f1", "type": "textarea", "label": "What reasonable mind said:"}, {"id": "f2", "type": "textarea", "label": "What wise mind might say:"}, {"id": "f3", "type": "textarea", "label": "How I will pause to ask next time:"}]'::jsonb, array['wise mind', 'core DBT', 'pause']::text[], '2026-10-31T15:00:00+00:00'::timestamptz),
  ('six-levels-of-validation-practice-sheet', 'Six Levels of Validation Practice Sheet', 'dbt'::resource_kind, 'A sheet for practicing validating a person at several levels, including yourself.', 'Use it to help a client practice making sense of their own or another person feeling.', array['Adults']::text[], '25 minutes', 'Walk the levels with a low-stakes example before a heated one. Many clients confuse validating with agreeing, so address that directly. Try a self-validating sentence aloud and see how it lands.', '[{"id": "f0", "type": "textarea", "label": "A feeling of mine that makes sense given what happened:"}, {"id": "f1", "type": "textarea", "label": "A sentence of validation I could say to someone else:"}, {"id": "f2", "type": "textarea", "label": "A sentence I could say to myself:"}, {"id": "f3", "type": "textarea", "label": "Where I will try one this week:"}]'::jsonb, array['validation', 'interpersonal effectiveness', 'self-validation']::text[], '2026-10-31T15:00:00+00:00'::timestamptz),
  ('riding-the-emotion-wave-time-log', 'Riding the Emotion Wave Time Log', 'dbt'::resource_kind, 'A log tracking how an emotion rises, peaks and falls when a client rides it out.', 'Use it to help a client see that an emotion has a shape and passes.', array['Adults', 'Teens']::text[], 'One week', 'Ask the client to log start time, peak rating and the time it eased, along with what they did. The data often shows waves are shorter than predicted. Never ask them to ride out anything unsafe.', '[{"id": "f0", "type": "textarea", "label": "The emotion and what set it off:"}, {"id": "f1", "type": "textarea", "label": "Its strength at the start and at the peak:"}, {"id": "f2", "type": "textarea", "label": "What I did while it was rising:"}, {"id": "f3", "type": "textarea", "label": "How long it took to ease:"}]'::jsonb, array['emotion regulation', 'diary card', 'distress tolerance']::text[], '2026-10-31T15:00:00+00:00'::timestamptz),
  ('radical-acceptance-daily-statement-page', 'Radical Acceptance Daily Statement Page', 'dbt'::resource_kind, 'A page for writing a short acceptance statement about something a client cannot change today.', 'Use it to help a client practice accepting a reality they cannot change right now.', array['Adults']::text[], '15 minutes', 'Acceptance is not approval, so say that early. Pick one situation, write one sentence, and have the client notice where resistance shows up in the body. Keep returning to the sentence rather than rewriting it daily.', '[{"id": "f0", "type": "textarea", "label": "What I am fighting that I cannot change today:"}, {"id": "f1", "type": "textarea", "label": "What accepting it would and would not mean:"}, {"id": "f2", "type": "textarea", "label": "My acceptance sentence:"}, {"id": "f3", "type": "textarea", "label": "Where I feel it in my body, and what helps:"}]'::jsonb, array['radical acceptance', 'acceptance', 'core DBT']::text[], '2026-10-31T15:00:00+00:00'::timestamptz),
  ('mindful-participation-choice-page', 'Mindful Participation Choice Page', 'dbt'::resource_kind, 'A page for choosing one everyday activity and joining it fully with attention.', 'Use it to help a client practice throwing themselves into one moment at a time.', array['Adults']::text[], 'Five minutes daily', 'Choose an ordinary activity, like washing dishes, to practice on. Ask the client to note what distracted them and how they came back. Expect the page to be short; that is fine.', '[{"id": "f0", "type": "textarea", "label": "The activity I chose:"}, {"id": "f1", "type": "textarea", "label": "What I noticed when I joined it fully:"}, {"id": "f2", "type": "textarea", "label": "What pulled my attention away:"}, {"id": "f3", "type": "textarea", "label": "How I came back:"}]'::jsonb, array['participate', 'mindfulness', 'skills practice']::text[], '2026-10-31T15:00:00+00:00'::timestamptz),
  ('weekly-couple-check-in-meeting-agenda', 'Weekly Couple Check-In Meeting Agenda', 'couples'::resource_kind, 'A short agenda for a regular weekly sit-down where partners cover appreciation, logistics and one concern.', 'Use it to help partners keep a steady, low-heat time to talk.', array['Couples']::text[], '30 minutes weekly', 'Each partner fills in their own part before the meeting. Keep to the agenda and a timer so concerns stay small. Coach them to end on appreciation, and ask what they would change about the meeting itself.', '[{"id": "f0", "type": "textarea", "label": "Partner A: something I appreciated about us this week:"}, {"id": "f1", "type": "textarea", "label": "Partner B: something I appreciated about us this week:"}, {"id": "f2", "type": "textarea", "label": "Partner A: one concern, stated as a need:"}, {"id": "f3", "type": "textarea", "label": "Partner B: one concern, stated as a need:"}]'::jsonb, array['Gottman', 'communication', 'weekly review']::text[], '2026-10-31T15:00:00+00:00'::timestamptz),
  ('stress-reducing-conversation-guide-for-two', 'Stress-Reducing Conversation Guide for Two', 'couples'::resource_kind, 'A guide for partners to take turns listening to each other talk about stress outside the relationship.', 'Use it to help partners support each other without fixing or arguing.', array['Couples']::text[], '20 minutes', 'Each partner gets ten minutes as speaker while the other only listens and shows interest. Coach against advice and against taking sides with the stressor. Debrief on what felt supportive.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what is weighing on me outside of us:"}, {"id": "f1", "type": "textarea", "label": "Partner B: what I heard, and how it felt to listen:"}, {"id": "f2", "type": "textarea", "label": "Partner B: what is weighing on me outside of us:"}, {"id": "f3", "type": "textarea", "label": "Partner A: what I heard, and how it felt to listen:"}]'::jsonb, array['Gottman', 'support', 'listening']::text[], '2026-10-31T15:00:00+00:00'::timestamptz),
  ('dreams-within-conflict-sharing-page', 'Dreams Within Conflict Sharing Page', 'couples'::resource_kind, 'A page for partners to look for the hope or story underneath a recurring disagreement.', 'Use it to help partners hear what a stuck disagreement means to each of them.', array['Couples']::text[], 'Full session', 'Choose one recurring disagreement and keep it a conversation, not a negotiation. Each partner takes a turn on what the issue means and what they hope for; the listener asks questions only. Expect emotion and set the pace.', '[{"id": "f0", "type": "textarea", "label": "Partner A: the issue and what it means to me:"}, {"id": "f1", "type": "textarea", "label": "Partner A: the hope or dream underneath it:"}, {"id": "f2", "type": "textarea", "label": "Partner B: the issue and what it means to me:"}, {"id": "f3", "type": "textarea", "label": "Partner B: the hope or dream underneath it:"}]'::jsonb, array['gridlock', 'Gottman', 'shared meaning']::text[], '2026-10-31T15:00:00+00:00'::timestamptz),
  ('pick-a-repair-menu-for-partners', 'Pick-a-Repair Menu for Partners', 'couples'::resource_kind, 'A menu of phrases and gestures partners agree on to interrupt a rising fight.', 'Use it to help partners choose repair moves ahead of time that both will accept.', array['Couples']::text[], '25 minutes', 'Have each partner write repairs they would welcome and ones they would not. Agree on a few of each, and practice one in a mild moment. The aim is a shared menu, so check each choice with both.', '[{"id": "f0", "type": "textarea", "label": "Partner A: repairs that would help me:"}, {"id": "f1", "type": "textarea", "label": "Partner A: repairs that would not:"}, {"id": "f2", "type": "textarea", "label": "Partner B: repairs that would help me:"}, {"id": "f3", "type": "textarea", "label": "Partner B: repairs that would not:"}]'::jsonb, array['repair', 'de-escalation', 'communication']::text[], '2026-10-31T15:00:00+00:00'::timestamptz),
  ('appreciation-swap-cards-for-partners', 'Appreciation Swap Cards for Partners', 'couples'::resource_kind, 'A set of cards for partners to write specific thank-yous and trade them during the week.', 'Use it to help partners notice and name small things the other does.', array['Couples']::text[], 'One week', 'Ask for specific, recent and small appreciation, not general praise. Partners trade cards in person rather than by text, if possible. Notice whether either dismisses what they receive and talk about it.', '[{"id": "f0", "type": "textarea", "label": "Partner A: three small things my partner did this week:"}, {"id": "f1", "type": "textarea", "label": "Partner A: how I will say thank you for one of them:"}, {"id": "f2", "type": "textarea", "label": "Partner B: three small things my partner did this week:"}, {"id": "f3", "type": "textarea", "label": "Partner B: how I will say thank you for one of them:"}]'::jsonb, array['appreciation', 'fondness and admiration', 'connection']::text[], '2026-10-31T15:00:00+00:00'::timestamptz),
  ('mood-weather-picture-window-craft', 'Mood Weather Picture Window Craft', 'kids'::resource_kind, 'A drawing craft where a child shows today feelings as weather in a window.', 'Use it to help a child name and draw how they are feeling today.', array['Children']::text[], '20 minutes', 'Give the child paper, crayons and a window frame to draw in. Let them pick any weather, and ask what the weather would do next rather than what is wrong. The parent can hang it up and ask about the weather at bedtime.', '[{"id": "f0", "type": "textarea", "label": "The weather in my window today:"}, {"id": "f1", "type": "textarea", "label": "The feeling that goes with it:"}, {"id": "f2", "type": "textarea", "label": "What would help the weather change:"}, {"id": "f3", "type": "textarea", "label": "Who I can tell about my weather:"}]'::jsonb, array['emotion recognition', 'art', 'children']::text[], '2026-10-31T15:00:00+00:00'::timestamptz),
  ('calm-jar-building-activity', 'Calm Jar Building Activity', 'kids'::resource_kind, 'A build-and-watch activity where a child shakes a jar of glitter and waits for it to settle.', 'Use it to help a child see a calm-down as something that takes a little time.', array['Children']::text[], '20 minutes', 'Build the jar together with water, glitter and a lid, then shake it. While it settles, practice slow breathing. The parent can keep a jar at home for the child to use by choice, never as a punishment.', '[{"id": "f0", "type": "textarea", "label": "What my jar looked like when it was shaken:"}, {"id": "f1", "type": "textarea", "label": "What I did while the glitter settled:"}, {"id": "f2", "type": "textarea", "label": "What my body felt like at the end:"}, {"id": "f3", "type": "textarea", "label": "Where we will keep our calm jar:"}]'::jsonb, array['calming', 'craft', 'children']::text[], '2026-10-31T15:00:00+00:00'::timestamptz),
  ('courage-cape-drawing-page', 'Courage Cape Drawing Page', 'kids'::resource_kind, 'A drawing page where a child designs a cape and writes what brave steps it helps with.', 'Use it to help a child connect small brave actions to a symbol they made.', array['Children']::text[], '20 minutes', 'Let the child decorate the cape any way they like, then add brave steps to it. Keep the steps small and the praise specific. A parent can help the child pick a step to try at home this week.', '[{"id": "f0", "type": "textarea", "label": "A brave thing I have done:"}, {"id": "f1", "type": "textarea", "label": "A brave thing I want to try:"}, {"id": "f2", "type": "textarea", "label": "What my cape looks like:"}, {"id": "f3", "type": "textarea", "label": "Who can cheer me on:"}]'::jsonb, array['courage', 'art', 'children']::text[], '2026-10-31T15:00:00+00:00'::timestamptz),
  ('feed-the-worry-monster-box-craft', 'Feed the Worry Monster Box Craft', 'kids'::resource_kind, 'A craft where a child makes a paper monster that takes folded worries.', 'Use it to help a child hand worries to an object instead of carrying them alone.', array['Children']::text[], '25 minutes', 'Build a monster from a box or bag with a mouth slot. The child writes or draws a worry, then feeds it in. The parent can open the box at a set time to listen. Do not ask for details a child does not want to give.', '[{"id": "f0", "type": "textarea", "label": "A worry I drew:"}, {"id": "f1", "type": "textarea", "label": "What my monster looks like:"}, {"id": "f2", "type": "textarea", "label": "What the monster says back:"}, {"id": "f3", "type": "textarea", "label": "Who will look at the worries with me:"}]'::jsonb, array['worry', 'craft', 'children']::text[], '2026-10-31T15:00:00+00:00'::timestamptz),
  ('kindness-tree-sticker-craft', 'Kindness Tree Sticker Craft', 'kids'::resource_kind, 'A paper tree where a child adds a leaf each time they notice a kind act.', 'Use it to help a child notice kindness given and received.', array['Children']::text[], '20 minutes then ongoing', 'Draw a bare tree and give the child leaf stickers. Count kindness received as well as given. The parent adds a leaf too, so it becomes a family habit rather than a chore.', '[{"id": "f0", "type": "textarea", "label": "A kind thing I did:"}, {"id": "f1", "type": "textarea", "label": "A kind thing someone did for me:"}, {"id": "f2", "type": "textarea", "label": "How the kind thing made me feel:"}, {"id": "f3", "type": "textarea", "label": "A kind thing I could do tomorrow:"}]'::jsonb, array['kindness', 'craft', 'children']::text[], '2026-10-31T15:00:00+00:00'::timestamptz),
  ('emotion-charades-turn-cards', 'Emotion Charades Turn Cards', 'game'::resource_kind, 'A charades game with feeling cards, used to read faces and body language.', 'Use it to help a group practice recognizing emotions from expression and posture.', array['Children', 'Teens', 'Groups']::text[], '20 minutes', 'Players take turns drawing a card and acting the feeling without words while others guess. Rules: no pointing at real people, and anyone can pass. Debrief on which feelings were easy to read and what clues helped.', '[{"id": "f0", "type": "textarea", "label": "A feeling I acted out:"}, {"id": "f1", "type": "textarea", "label": "A feeling that was hard to guess:"}, {"id": "f2", "type": "textarea", "label": "Clues that help me read someone feeling:"}, {"id": "f3", "type": "textarea", "label": "A time I showed a feeling without saying it:"}]'::jsonb, array['emotion recognition', 'charades', 'game']::text[], '2026-10-31T15:00:00+00:00'::timestamptz),
  ('skill-sort-speed-round', 'Skill Sort Speed Round', 'game'::resource_kind, 'A card-sorting race that places coping skills into groups such as move, think, connect and breathe.', 'Use it to help a group see how many ways there are to cope.', array['Teens', 'Adults', 'Groups']::text[], '20 minutes', 'Teams race to sort skill cards into the groups, with one point for each fit and a bonus for a new skill idea. Rules: no arguing during the round. Debrief on which skills each person would try this week.', '[{"id": "f0", "type": "textarea", "label": "A skill I knew already:"}, {"id": "f1", "type": "textarea", "label": "A skill I want to try:"}, {"id": "f2", "type": "textarea", "label": "A group I do not use much:"}, {"id": "f3", "type": "textarea", "label": "When I would reach for my pick:"}]'::jsonb, array['skills', 'coping skills card', 'game']::text[], '2026-10-31T15:00:00+00:00'::timestamptz),
  ('fact-fact-value-guess-the-value-game', 'Fact Fact Value Guess the Value Game', 'game'::resource_kind, 'A turn-based game where players share two true facts and one value that guides them.', 'Use it to help group members get to know each other through what matters to them.', array['Teens', 'Adults', 'Groups']::text[], '20 minutes', 'Each player offers two facts and a value and the group guesses which is the value. Rules: everyone may pass, and no one comments on a value negatively. Debrief on what surprised them.', '[{"id": "f0", "type": "textarea", "label": "Two true facts about me:"}, {"id": "f1", "type": "textarea", "label": "One value that guides me:"}, {"id": "f2", "type": "textarea", "label": "What I learned about someone else:"}, {"id": "f3", "type": "textarea", "label": "How it felt to share a value:"}]'::jsonb, array['values', 'icebreaker', 'game']::text[], '2026-10-31T15:00:00+00:00'::timestamptz),
  ('thought-or-fact-toss-game', 'Thought or Fact Toss Game', 'game'::resource_kind, 'A toss game where players call a statement either a thought or a fact before they catch the ball.', 'Use it to help a group practice telling a thought from a fact.', array['Teens', 'Adults', 'Groups']::text[], '15 minutes', 'The leader reads a statement, tosses the ball, and the catcher says thought or fact and why. Rules: a pass is always allowed. Debrief on which statements were tricky and why a thought can feel like a fact.', '[{"id": "f0", "type": "textarea", "label": "A statement that was tricky:"}, {"id": "f1", "type": "textarea", "label": "A thought of mine that feels like a fact:"}, {"id": "f2", "type": "textarea", "label": "How I can check it:"}, {"id": "f3", "type": "textarea", "label": "What I will do when I notice it:"}]'::jsonb, array['thoughts', 'cognitive distortions', 'game']::text[], '2026-10-31T15:00:00+00:00'::timestamptz),
  ('gratitude-stack-question-game', 'Gratitude Stack Question Game', 'game'::resource_kind, 'A stacking game where each player answers a gratitude question before adding a block.', 'Use it to help a group share things they appreciate in a light, low-pressure way.', array['Children', 'Teens', 'Groups']::text[], '20 minutes', 'Players answer a question card to add a block to the tower, and a collapse just starts a new round. Rules: answers can be small, and a pass is allowed. Debrief on what it was like to hear others answers.', '[{"id": "f0", "type": "textarea", "label": "A thing I am glad for today:"}, {"id": "f1", "type": "textarea", "label": "A person I appreciate:"}, {"id": "f2", "type": "textarea", "label": "Something small that went right:"}, {"id": "f3", "type": "textarea", "label": "What I heard from others that I liked:"}]'::jsonb, array['gratitude', 'game night', 'game']::text[], '2026-10-31T15:00:00+00:00'::timestamptz),
  ('trauma-reminder-orienting-card', 'Trauma Reminder Orienting Card', 'worksheet'::resource_kind, 'A pocket card of orienting steps for when a reminder pulls a client out of the present.', 'Use it to help a client come back to the here and now when a reminder hits.', array['Adults']::text[], '15 minutes', 'Build the card in session while the client is steady, and choose steps they can do quietly in public. Let them decide what goes on it. No details of past events are needed; the card is only about the present room.', '[{"id": "f0", "type": "textarea", "label": "Three things I can see right now:"}, {"id": "f1", "type": "textarea", "label": "A sound or texture that tells me I am here:"}, {"id": "f2", "type": "textarea", "label": "The date, the place and who is with me:"}, {"id": "f3", "type": "textarea", "label": "Who I can reach if I need support:"}]'::jsonb, array['PTSD and trauma', 'orienting', 'grounding']::text[], '2026-10-31T15:00:00+00:00'::timestamptz),
  ('then-versus-now-reminder-sort-page', 'Then Versus Now Reminder Sort Page', 'cbt'::resource_kind, 'A page sorting what belongs to the past from what is true in the present moment.', 'Use it to help a client separate a reminder from current safety.', array['Adults']::text[], '20 minutes', 'Work with present facts only, such as where the client is and who is there. Never ask for a written account of the past. Pace it, and stop if the client seems to drift or flood; use a grounding step instead.', '[{"id": "f0", "type": "textarea", "label": "A reminder that showed up this week:"}, {"id": "f1", "type": "textarea", "label": "What is different about now:"}, {"id": "f2", "type": "textarea", "label": "Facts that tell me I am safe at this moment:"}, {"id": "f3", "type": "textarea", "label": "A sentence I can say to myself:"}]'::jsonb, array['PTSD and trauma', 'orienting', 'safety']::text[], '2026-10-31T15:00:00+00:00'::timestamptz),
  ('carrying-your-story-with-care-page', 'Carrying Your Story With Care Page', 'act'::resource_kind, 'A page on choosing values-based actions while the past is still part of life.', 'Use it to help a client move toward values at a pace that feels safe.', array['Adults']::text[], '25 minutes', 'Keep to values and present actions rather than events. Offer pacing and say the client can skip any prompt. Notice whether willingness is being confused with forcing; slowing down is also a values choice.', '[{"id": "f0", "type": "textarea", "label": "What matters to me in how I live now:"}, {"id": "f1", "type": "textarea", "label": "A small step toward it that feels safe:"}, {"id": "f2", "type": "textarea", "label": "What I will bring with me while I take it:"}, {"id": "f3", "type": "textarea", "label": "Who supports me and how I ask for it:"}]'::jsonb, array['PTSD and trauma', 'values', 'pacing']::text[], '2026-10-31T15:00:00+00:00'::timestamptz),
  ('safe-place-anchor-and-self-soothe-plan', 'Safe Place Anchor and Self-Soothe Plan', 'dbt'::resource_kind, 'A plan listing five-senses comforts and a safe-place image a client can use when overwhelmed.', 'Use it to help a client build a set of self-soothing steps before they need them.', array['Adults']::text[], '25 minutes', 'Build the plan while calm and test each item in session. Some images or smells may be unwelcome, so ask and keep the client in charge. Stay on comfort, never on content from the past.', '[{"id": "f0", "type": "textarea", "label": "Something I see that calms me:"}, {"id": "f1", "type": "textarea", "label": "Something I hear that calms me:"}, {"id": "f2", "type": "textarea", "label": "Something I touch or smell that helps:"}, {"id": "f3", "type": "textarea", "label": "My safe-place image in three words:"}]'::jsonb, array['PTSD and trauma', 'self-soothe', 'distress tolerance']::text[], '2026-10-31T15:00:00+00:00'::timestamptz),
  ('safe-helpers-feelings-map-craft', 'Safe Helpers Feelings Map Craft', 'kids'::resource_kind, 'A drawing craft for a child to map people and places that help them feel safe.', 'Use it to help a child name where and with whom they feel safe.', array['Children']::text[], '25 minutes', 'Let the child draw rooms, people and pets that help them feel safe. A parent joins at the end to learn who is on the map. Know your reporting duties in case the child discloses; do not probe, listen and respond calmly.', '[{"id": "f0", "type": "textarea", "label": "Places where I feel safe:"}, {"id": "f1", "type": "textarea", "label": "People who help me feel safe:"}, {"id": "f2", "type": "textarea", "label": "What I do when I feel scared:"}, {"id": "f3", "type": "textarea", "label": "The grown-up I would tell if something felt wrong:"}]'::jsonb, array['PTSD and trauma', 'safety', 'craft', 'children']::text[], '2026-10-31T15:00:00+00:00'::timestamptz),
  ('anxiety-body-signals-map-page', 'Anxiety Body Signals Map Page', 'worksheet'::resource_kind, 'A body outline for marking where anxiety shows up and what each signal says.', 'Use it to help a client notice early body signals of anxiety.', array['Adults', 'Teens']::text[], '20 minutes', 'Have the client color the places they feel it and label the signal. Many clients are surprised how early it begins. Use the map later to pick a skill by location, such as slow exhales for a tight chest.', '[{"id": "f0", "type": "textarea", "label": "Where I feel anxiety first:"}, {"id": "f1", "type": "textarea", "label": "What it feels like in that spot:"}, {"id": "f2", "type": "textarea", "label": "What it tries to tell me:"}, {"id": "f3", "type": "textarea", "label": "A small thing that eases that spot:"}]'::jsonb, array['anxiety', 'body signals', 'awareness']::text[], '2026-10-31T15:00:00+00:00'::timestamptz),
  ('sitting-with-maybe-experiment-planner', 'Sitting With Maybe Experiment Planner', 'cbt'::resource_kind, 'A planner for testing a feared outcome by doing a small thing and noting what happens.', 'Use it to help a client test a prediction against what actually happens.', array['Adults']::text[], '25 minutes', 'Choose a small, safe experiment tied to a specific prediction and have the client rate belief beforehand. Collect results without spin. If the prediction does not come true, ask what it suggests; if it does, plan how they coped.', '[{"id": "f0", "type": "textarea", "label": "The prediction I want to test:"}, {"id": "f1", "type": "textarea", "label": "How much I believe it, zero to ten:"}, {"id": "f2", "type": "textarea", "label": "The experiment, step by step:"}, {"id": "f3", "type": "textarea", "label": "What actually happened:"}]'::jsonb, array['anxiety', 'behavioral experiment', 'uncertainty']::text[], '2026-10-31T15:00:00+00:00'::timestamptz),
  ('anxiety-as-passenger-values-drive-page', 'Anxiety as Passenger Values Drive Page', 'act'::resource_kind, 'A page placing anxiety as a passenger while the client drives toward a chosen value.', 'Use it to help a client act on a value with anxiety along for the ride.', array['Adults']::text[], '25 minutes', 'Use the driving metaphor loosely and let the client edit it. Name what anxiety says to turn back, and have them list what they would still choose to do. Choose one real drive to take this week.', '[{"id": "f0", "type": "textarea", "label": "Where I want to drive this week:"}, {"id": "f1", "type": "textarea", "label": "What anxiety says as I go:"}, {"id": "f2", "type": "textarea", "label": "What I would still do:"}, {"id": "f3", "type": "textarea", "label": "One step I will take, with a day:"}]'::jsonb, array['anxiety', 'passengers on the bus', 'values']::text[], '2026-10-31T15:00:00+00:00'::timestamptz),
  ('paced-breathing-and-cool-water-skills-page', 'Paced Breathing and Cool Water Skills Page', 'dbt'::resource_kind, 'A page for trying paced breathing and cool-water skills and rating what helps most.', 'Use it to help a client find which quick body skills lower anxious arousal.', array['Adults', 'Teens']::text[], '20 minutes', 'Try each skill in session and compare ratings before and after. Skip cold-water steps if the client has a medical reason to avoid them and check that first. Let the client pick the two that work best for their kit.', '[{"id": "f0", "type": "textarea", "label": "My anxiety before, zero to ten:"}, {"id": "f1", "type": "textarea", "label": "Skill I tried and my rating after:"}, {"id": "f2", "type": "textarea", "label": "The second skill and my rating:"}, {"id": "f3", "type": "textarea", "label": "The one I will keep in my kit:"}]'::jsonb, array['anxiety', 'breathing', 'distress tolerance']::text[], '2026-10-31T15:00:00+00:00'::timestamptz),
  ('worry-or-plan-sorting-game', 'Worry or Plan Sorting Game', 'game'::resource_kind, 'A card game sorting worries into those a person can act on and those to let float by.', 'Use it to help a group tell a worry they can act on from one they cannot.', array['Adults', 'Teens', 'Groups']::text[], '20 minutes', 'Players write worries on cards and sort them into act or let float, with the group offering a question rather than advice. Rules: pass anytime, and keep details private. Debrief on which pile was bigger.', '[{"id": "f0", "type": "textarea", "label": "A worry I could act on:"}, {"id": "f1", "type": "textarea", "label": "A worry I cannot control:"}, {"id": "f2", "type": "textarea", "label": "What I do with each:"}, {"id": "f3", "type": "textarea", "label": "What I take from the game:"}]'::jsonb, array['anxiety', 'worry', 'game']::text[], '2026-10-31T15:00:00+00:00'::timestamptz),
  ('low-mood-day-menu-of-small-things', 'Low Mood Day Menu of Small Things', 'worksheet'::resource_kind, 'A menu of tiny actions sorted by effort so a client can pick one on a hard day.', 'Use it to help a client choose a small action when motivation is low.', array['Adults']::text[], '20 minutes', 'Build the menu when the client feels relatively steady, with appetizers that take two minutes. Ask them to name what is realistic, not what they think they should do. Review which items they used.', '[{"id": "f0", "type": "textarea", "label": "Two-minute things I can do:"}, {"id": "f1", "type": "textarea", "label": "Ten-minute things I can do:"}, {"id": "f2", "type": "textarea", "label": "Things that include another person:"}, {"id": "f3", "type": "textarea", "label": "The one I will pick next time:"}]'::jsonb, array['depression', 'small steps', 'activity scheduling']::text[], '2026-10-31T15:00:00+00:00'::timestamptz),
  ('mood-and-activity-pattern-chart', 'Mood and Activity Pattern Chart', 'cbt'::resource_kind, 'A chart connecting activities with mood ratings to find what lifts and what drains.', 'Use it to help a client see which activities connect with better or worse mood.', array['Adults']::text[], 'One week', 'Have the client rate pleasure and mastery from zero to ten for each entry. Look for surprise and for days with nothing scheduled. Pick one activity to add and one to adjust.', '[{"id": "f0", "type": "textarea", "label": "An activity and my mood during it:"}, {"id": "f1", "type": "textarea", "label": "Pleasure rating and mastery rating:"}, {"id": "f2", "type": "textarea", "label": "Activities that lifted my mood:"}, {"id": "f3", "type": "textarea", "label": "One I will add this week:"}]'::jsonb, array['depression', 'behavioral activation', 'mood tracking']::text[], '2026-10-31T15:00:00+00:00'::timestamptz),
  ('values-over-mood-daily-choice-page', 'Values Over Mood Daily Choice Page', 'act'::resource_kind, 'A page for choosing a values-based action even when mood is low.', 'Use it to help a client act on a value without waiting for mood to change.', array['Adults']::text[], '20 minutes', 'Separate how the client feels from what they choose to do. Keep the step tiny and ask what they are willing to feel while doing it. Do not frame it as fixing mood.', '[{"id": "f0", "type": "textarea", "label": "What I value that I miss doing:"}, {"id": "f1", "type": "textarea", "label": "What my mood says today:"}, {"id": "f2", "type": "textarea", "label": "A tiny action I can do anyway:"}, {"id": "f3", "type": "textarea", "label": "How I will notice I did it:"}]'::jsonb, array['depression', 'values', 'committed action']::text[], '2026-10-31T15:00:00+00:00'::timestamptz),
  ('opposite-action-for-withdrawal-page', 'Opposite Action for Withdrawal Page', 'dbt'::resource_kind, 'A page for noticing the urge to withdraw and choosing a small opposite step.', 'Use it to help a client try a small opposite action when they feel like pulling away.', array['Adults']::text[], '20 minutes', 'Check whether withdrawal fits the facts before suggesting the opposite. Keep the opposite action gentle, like a text or a step outside. Review what happened afterward without judging.', '[{"id": "f0", "type": "textarea", "label": "The urge I notice:"}, {"id": "f1", "type": "textarea", "label": "Does it fit the facts of the situation?"}, {"id": "f2", "type": "textarea", "label": "A small opposite action I could try:"}, {"id": "f3", "type": "textarea", "label": "What happened when I tried:"}]'::jsonb, array['depression', 'opposite action', 'emotion regulation']::text[], '2026-10-31T15:00:00+00:00'::timestamptz),
  ('gloomy-cloud-brightening-craft', 'Gloomy Cloud Brightening Craft', 'kids'::resource_kind, 'A craft where a child draws a gloomy cloud and adds small things that brighten it.', 'Use it to help a child find small things that brighten a heavy day.', array['Children']::text[], '25 minutes', 'Let the child color a gray cloud and then add colors with each brightener they name. The parent helps pick one brightener to try at home and checks in at bedtime. Keep it light and let the child lead the pace.', '[{"id": "f0", "type": "textarea", "label": "What my gloomy cloud looks like:"}, {"id": "f1", "type": "textarea", "label": "Things that make my cloud a little brighter:"}, {"id": "f2", "type": "textarea", "label": "Who helps me when I feel gloomy:"}, {"id": "f3", "type": "textarea", "label": "One brightener I will try tomorrow:"}]'::jsonb, array['depression', 'craft', 'mood', 'children']::text[], '2026-10-31T15:00:00+00:00'::timestamptz),
  ('start-line-task-launch-checklist', 'Start Line Task Launch Checklist', 'worksheet'::resource_kind, 'A short checklist that breaks the first two minutes of a task into physical steps.', 'Use it to help a client get started on a task they keep putting off.', array['Adults', 'Teens']::text[], '15 minutes', 'Pick one task the client avoids and write out the first physical actions, such as opening the file. Keep the list short enough to read at a glance. Ask what makes starting hard and adjust the list around it.', '[{"id": "f0", "type": "textarea", "label": "The task I keep putting off:"}, {"id": "f1", "type": "textarea", "label": "The very first physical step:"}, {"id": "f2", "type": "textarea", "label": "The second and third steps:"}, {"id": "f3", "type": "textarea", "label": "What will remind me to start:"}]'::jsonb, array['ADHD', 'task initiation', 'executive skills']::text[], '2026-10-31T15:00:00+00:00'::timestamptz),
  ('time-guess-and-check-log', 'Time Guess and Check Log', 'cbt'::resource_kind, 'A log comparing how long a client thinks a task will take with how long it did.', 'Use it to help a client build a more realistic sense of time.', array['Adults', 'Teens']::text[], 'One week', 'Have the client guess before and time it afterward, with no judgment about misses. Look for consistent over or under guessing and add a buffer. The log gives you a pattern to discuss.', '[{"id": "f0", "type": "textarea", "label": "The task and my guess:"}, {"id": "f1", "type": "textarea", "label": "How long it actually took:"}, {"id": "f2", "type": "textarea", "label": "What made it longer or shorter:"}, {"id": "f3", "type": "textarea", "label": "The buffer I will add next time:"}]'::jsonb, array['ADHD', 'time management', 'monitoring']::text[], '2026-10-31T15:00:00+00:00'::timestamptz),
  ('interest-and-values-anchor-page', 'Interest and Values Anchor Page', 'act'::resource_kind, 'A page linking an attention-heavy task to the value behind it to help with sticking with it.', 'Use it to help a client connect a dull task to something that matters to them.', array['Adults']::text[], '20 minutes', 'Pick a task that feels pointless and ask what it serves. Do not turn it into forced motivation; some tasks stay dull. Let the client pick a cue that reminds them why.', '[{"id": "f0", "type": "textarea", "label": "A task that feels dull:"}, {"id": "f1", "type": "textarea", "label": "What it makes possible:"}, {"id": "f2", "type": "textarea", "label": "The value behind it:"}, {"id": "f3", "type": "textarea", "label": "A cue that will remind me:"}]'::jsonb, array['ADHD', 'values', 'motivation']::text[], '2026-10-31T15:00:00+00:00'::timestamptz),
  ('focus-flag-body-break-game', 'Focus Flag Body Break Game', 'kids'::resource_kind, 'A game where a child moves for a short burst and then raises a flag for a focus round.', 'Use it to help a child alternate movement and focus in short rounds.', array['Children']::text[], '20 minutes', 'Set a visible timer for two or three minutes of seated focus followed by a movement round. The parent can use the same rhythm for homework. Praise the effort and adjust the timer length to the child.', '[{"id": "f0", "type": "textarea", "label": "My favorite movement break:"}, {"id": "f1", "type": "textarea", "label": "How long I could focus before the timer:"}, {"id": "f2", "type": "textarea", "label": "What helped me stay with it:"}, {"id": "f3", "type": "textarea", "label": "How we will use it at home:"}]'::jsonb, array['ADHD', 'movement', 'focus', 'children']::text[], '2026-10-31T15:00:00+00:00'::timestamptz),
  ('next-step-relay-organizing-game', 'Next Step Relay Organizing Game', 'game'::resource_kind, 'A relay game where teams sort tasks and name the first step for each.', 'Use it to help a group practice naming the next step on a big task.', array['Teens', 'Adults', 'Groups']::text[], '20 minutes', 'Teams pull a task card and race to name its first step and a reminder. Rules: steps must be concrete, and anyone can swap a card. Debrief on which tasks were easiest to start and why.', '[{"id": "f0", "type": "textarea", "label": "A task I drew:"}, {"id": "f1", "type": "textarea", "label": "The first step I named:"}, {"id": "f2", "type": "textarea", "label": "A reminder that would work for me:"}, {"id": "f3", "type": "textarea", "label": "What I will use from the game:"}]'::jsonb, array['ADHD', 'executive function', 'planning', 'game']::text[], '2026-10-31T15:00:00+00:00'::timestamptz),
  ('urge-wave-tracker-for-substance-use', 'Urge Wave Tracker for Substance Use', 'worksheet'::resource_kind, 'A tracker for noting when urges rise, how strong they get and what was happening.', 'Use it to help a client see the shape and triggers of urges to use a substance.', array['Adults']::text[], 'One week', 'Ask for time, place, feeling and strength zero to ten, and what the client did. Treat all entries as information, whatever happened. Look together for patterns in time and setting.', '[{"id": "f0", "type": "textarea", "label": "When the urge showed up and how strong:"}, {"id": "f1", "type": "textarea", "label": "What was happening around me:"}, {"id": "f2", "type": "textarea", "label": "What I did with the urge:"}, {"id": "f3", "type": "textarea", "label": "Something I want to try next time:"}]'::jsonb, array['addiction', 'urges', 'substance use', 'tracking']::text[], '2026-10-31T15:00:00+00:00'::timestamptz),
  ('triggers-and-alternatives-plan-for-substance-use', 'Triggers and Alternatives Plan for Substance Use', 'cbt'::resource_kind, 'A plan pairing common triggers with alternative responses a client chooses.', 'Use it to help a client plan responses for situations that bring up urges.', array['Adults']::text[], '30 minutes', 'List triggers by person, place, feeling and time of day, and match each to a response the client picks. Rehearse one aloud. Revisit the plan often as triggers shift.', '[{"id": "f0", "type": "textarea", "label": "A trigger I know well:"}, {"id": "f1", "type": "textarea", "label": "What I usually do next:"}, {"id": "f2", "type": "textarea", "label": "An alternative I could try:"}, {"id": "f3", "type": "textarea", "label": "Who I can contact if the urge is strong:"}]'::jsonb, array['addiction', 'triggers', 'relapse prevention']::text[], '2026-10-31T15:00:00+00:00'::timestamptz),
  ('urge-surfing-with-values-page', 'Urge Surfing With Values Page', 'act'::resource_kind, 'A page for noticing an urge, staying with it and choosing a values-based action.', 'Use it to help a client stay with an urge and still choose what matters to them.', array['Adults']::text[], '25 minutes', 'Practice noticing an urge together using a small non-substance example first. Ask what the client values that the urge pulls away from. Keep the tone nonjudgmental about slips.', '[{"id": "f0", "type": "textarea", "label": "Where I feel the urge in my body:"}, {"id": "f1", "type": "textarea", "label": "What the urge tells me to do:"}, {"id": "f2", "type": "textarea", "label": "What I value that I want to protect:"}, {"id": "f3", "type": "textarea", "label": "What I did instead:"}]'::jsonb, array['addiction', 'urges', 'values', 'acceptance']::text[], '2026-10-31T15:00:00+00:00'::timestamptz),
  ('pros-and-cons-of-using-page', 'Pros and Cons of Using Page', 'dbt'::resource_kind, 'A DBT-style page weighing short-term and long-term pros and cons of using or not using.', 'Use it to help a client look honestly at both sides of a choice about substance use.', array['Adults']::text[], '25 minutes', 'Fill in all four boxes, including what use gives them. Skipping the real pros makes the page feel like a lecture. Leave the decision to the client and note ambivalence as it shows.', '[{"id": "f0", "type": "textarea", "label": "Pros of using in the short term:"}, {"id": "f1", "type": "textarea", "label": "Cons of using in the long term:"}, {"id": "f2", "type": "textarea", "label": "Pros of not using:"}, {"id": "f3", "type": "textarea", "label": "What tips the scale for me today:"}]'::jsonb, array['addiction', 'pros and cons', 'ambivalence', 'substance use']::text[], '2026-10-31T15:00:00+00:00'::timestamptz),
  ('support-without-rescuing-conversation-guide', 'Support Without Rescuing Conversation Guide', 'couples'::resource_kind, 'A guide for partners to discuss how to support recovery without policing or rescuing.', 'Use it to help partners agree on helpful and unhelpful kinds of support.', array['Couples']::text[], '30 minutes', 'Each partner lists what would help and what feels controlling. Compare lists and agree on a few changes to try. Partners may need their own support, so mention that.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what helps me feel supported:"}, {"id": "f1", "type": "textarea", "label": "Partner A: what feels like policing:"}, {"id": "f2", "type": "textarea", "label": "Partner B: what I am able to offer:"}, {"id": "f3", "type": "textarea", "label": "Partner B: what I need for myself:"}]'::jsonb, array['addiction', 'support', 'boundaries', 'substance use']::text[], '2026-10-31T15:00:00+00:00'::timestamptz),
  ('anger-early-warning-thermometer-page', 'Anger Early Warning Thermometer Page', 'worksheet'::resource_kind, 'A thermometer page marking early body signs of anger before it boils.', 'Use it to help a client spot anger earlier and choose a response sooner.', array['Adults', 'Teens']::text[], '20 minutes', 'Color the thermometer with body cues, thoughts and actions at each level. Anger often follows hurt or fear, so ask what is under it. Pick one action for each of the lower levels.', '[{"id": "f0", "type": "textarea", "label": "Body signs at the low end:"}, {"id": "f1", "type": "textarea", "label": "Thoughts I have as it climbs:"}, {"id": "f2", "type": "textarea", "label": "What I do at the top:"}, {"id": "f3", "type": "textarea", "label": "An action I will try at the lower end:"}]'::jsonb, array['anger management', 'early warning signs', 'awareness']::text[], '2026-10-31T15:00:00+00:00'::timestamptz),
  ('anger-trigger-thought-record', 'Anger Trigger Thought Record', 'cbt'::resource_kind, 'A thought record for the thought that sits between a trigger and an angry reaction.', 'Use it to help a client find the thought that fuels anger.', array['Adults']::text[], '25 minutes', 'Choose a recent episode and slow it down: the trigger, the thought, the feeling and the action. Look for words such as always and should. Draft a more balanced thought they can believe.', '[{"id": "f0", "type": "textarea", "label": "What set me off:"}, {"id": "f1", "type": "textarea", "label": "What I told myself:"}, {"id": "f2", "type": "textarea", "label": "How angry I felt and what I did:"}, {"id": "f3", "type": "textarea", "label": "A more balanced thought:"}]'::jsonb, array['anger management', 'thought record', 'triggers']::text[], '2026-10-31T15:00:00+00:00'::timestamptz),
  ('anger-and-values-choice-point-page', 'Anger and Values Choice Point Page', 'act'::resource_kind, 'A page mapping an angry moment as a choice point between the pull of anger and a value.', 'Use it to help a client see a choice between reacting and acting on a value.', array['Adults']::text[], '25 minutes', 'Draw a choice point with the pull on one side and the value on the other. Ask what they want to be doing in the moment. Anger is not wrong; the question is what they do with it.', '[{"id": "f0", "type": "textarea", "label": "The situation that angers me:"}, {"id": "f1", "type": "textarea", "label": "What I feel pulled to do:"}, {"id": "f2", "type": "textarea", "label": "What I would like to stand for:"}, {"id": "f3", "type": "textarea", "label": "A move I can make in the moment:"}]'::jsonb, array['anger management', 'choice point', 'values']::text[], '2026-10-31T15:00:00+00:00'::timestamptz),
  ('cooling-down-time-out-plan-for-two', 'Cooling Down Time-Out Plan for Two', 'couples'::resource_kind, 'A plan for partners to pause a heated talk and come back to it.', 'Use it to help partners agree how to pause and return to a heated moment.', array['Couples']::text[], '25 minutes', 'Agree on a signal, a length of at least twenty minutes and a time to come back. Each partner should know what they will do while apart. Practice using the signal when calm.', '[{"id": "f0", "type": "textarea", "label": "Partner A: the signal I will use:"}, {"id": "f1", "type": "textarea", "label": "Partner A: what I will do while apart:"}, {"id": "f2", "type": "textarea", "label": "Partner B: the signal I will use:"}, {"id": "f3", "type": "textarea", "label": "Partner B: how I will come back to the talk:"}]'::jsonb, array['anger management', 'de-escalation', 'communication']::text[], '2026-10-31T15:00:00+00:00'::timestamptz),
  ('volcano-calm-down-craft', 'Volcano Calm Down Craft', 'kids'::resource_kind, 'A craft where a child builds a volcano and names what to do as it rumbles.', 'Use it to help a child learn to notice anger early and cool it down.', array['Children']::text[], '25 minutes', 'Build the volcano and label the steps from rumbling to eruption. Practice a cool-down at each stage. The parent learns the steps too and can cue them without scolding.', '[{"id": "f0", "type": "textarea", "label": "What my volcano feels like when it rumbles:"}, {"id": "f1", "type": "textarea", "label": "What I can do when it rumbles:"}, {"id": "f2", "type": "textarea", "label": "What helps me cool down:"}, {"id": "f3", "type": "textarea", "label": "What my grown-up can say to help:"}]'::jsonb, array['anger management', 'calm down', 'craft', 'children']::text[], '2026-10-31T15:00:00+00:00'::timestamptz),
  ('intrusive-thought-and-ritual-loop-map', 'Intrusive Thought and Ritual Loop Map', 'worksheet'::resource_kind, 'A map of the loop from an intrusive thought to the urge to do something and the brief relief.', 'Use it to help a client see how a ritual keeps the loop going.', array['Adults', 'Teens']::text[], '25 minutes', 'Map one real loop with the client, step by step. Keep the language curious and avoid asking for reassurance on the content of the thought. The map is the starting point for choosing a small step later.', '[{"id": "f0", "type": "textarea", "label": "The thought or image that showed up:"}, {"id": "f1", "type": "textarea", "label": "The feeling that came with it:"}, {"id": "f2", "type": "textarea", "label": "What I did to feel better:"}, {"id": "f3", "type": "textarea", "label": "What happened to the feeling afterward:"}]'::jsonb, array['OCD', 'intrusive thoughts', 'maintenance cycle']::text[], '2026-10-31T15:00:00+00:00'::timestamptz),
  ('small-step-response-delay-log', 'Small Step Response Delay Log', 'cbt'::resource_kind, 'A log for delaying a ritual by a few minutes and noting what happens to the urge.', 'Use it to help a client practice waiting before a ritual at a pace they choose.', array['Adults']::text[], 'One week', 'Agree on a short delay the client chooses and rate the urge before and after. Do not push beyond what they have agreed. Review the numbers together and plan a slightly longer wait only if they want one.', '[{"id": "f0", "type": "textarea", "label": "The urge and my rating from zero to ten:"}, {"id": "f1", "type": "textarea", "label": "How long I waited:"}, {"id": "f2", "type": "textarea", "label": "My rating at the end of the wait:"}, {"id": "f3", "type": "textarea", "label": "What I noticed:"}]'::jsonb, array['OCD', 'response delay', 'compulsions', 'exposure']::text[], '2026-10-31T15:00:00+00:00'::timestamptz),
  ('letting-the-thought-be-here-page', 'Letting the Thought Be Here Page', 'act'::resource_kind, 'A page for allowing an intrusive thought to be present while the client does something that matters.', 'Use it to help a client let a thought sit nearby while acting on a value.', array['Adults']::text[], '20 minutes', 'Practice with a neutral thought before an intrusive one. Emphasize willingness over getting rid of the thought. Ask what the client wants to be doing when the thought shows up.', '[{"id": "f0", "type": "textarea", "label": "A thought that visits often:"}, {"id": "f1", "type": "textarea", "label": "What I usually do when it arrives:"}, {"id": "f2", "type": "textarea", "label": "What I want to be doing instead:"}, {"id": "f3", "type": "textarea", "label": "What I am willing to feel while I do it:"}]'::jsonb, array['OCD', 'intrusive thoughts', 'willingness', 'defusion']::text[], '2026-10-31T15:00:00+00:00'::timestamptz),
  ('reassurance-request-agreement-for-partners', 'Reassurance Request Agreement for Partners', 'couples'::resource_kind, 'A page where partners agree together how to respond when asked for reassurance.', 'Use it to help partners respond to reassurance requests in a way both can live with.', array['Couples']::text[], '30 minutes', 'Both partners should agree on the wording and on what the partner will say kindly. Avoid making it a rule one person imposes. Revisit it in a few weeks and adjust together.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what I am asking for when I ask for reassurance:"}, {"id": "f1", "type": "textarea", "label": "Partner A: what I would like to hear instead:"}, {"id": "f2", "type": "textarea", "label": "Partner B: what it is like to be asked:"}, {"id": "f3", "type": "textarea", "label": "Partner B: a kind sentence I can offer:"}]'::jsonb, array['OCD', 'reassurance seeking', 'accommodation']::text[], '2026-10-31T15:00:00+00:00'::timestamptz),
  ('bossy-worry-brain-drawing-page', 'Bossy Worry Brain Drawing Page', 'kids'::resource_kind, 'A page where a child draws their worry brain as a bossy character and talks back to it.', 'Use it to help a child separate themselves from a bossy worry voice.', array['Children']::text[], '25 minutes', 'Let the child draw the character and give it a silly name. Practice a few things to say back to it. The parent learns to say what the worry brain is doing rather than answering its questions repeatedly.', '[{"id": "f0", "type": "textarea", "label": "What my worry brain looks like:"}, {"id": "f1", "type": "textarea", "label": "What it bosses me to do:"}, {"id": "f2", "type": "textarea", "label": "What I can say back:"}, {"id": "f3", "type": "textarea", "label": "What my grown-up can say to help:"}]'::jsonb, array['OCD', 'externalizing', 'children', 'worry']::text[], '2026-10-31T15:00:00+00:00'::timestamptz),
  ('panic-rise-and-fall-minute-chart', 'Panic Rise and Fall Minute Chart', 'worksheet'::resource_kind, 'A chart where a client rates the rise and fall of a panic wave minute by minute.', 'Use it to help a client see that a panic wave rises and falls.', array['Adults', 'Teens']::text[], '20 minutes', 'Look at the shape of the wave together. Clients often underestimate how soon it eases. Use their own record instead of reassurance, and note what they did during it.', '[{"id": "f0", "type": "textarea", "label": "What I was doing when it started:"}, {"id": "f1", "type": "textarea", "label": "Intensity every few minutes:"}, {"id": "f2", "type": "textarea", "label": "When it started to ease:"}, {"id": "f3", "type": "textarea", "label": "What I noticed about the wave:"}]'::jsonb, array['panic attacks', 'panic', 'body sensations']::text[], '2026-10-31T15:00:00+00:00'::timestamptz),
  ('body-sensation-meaning-check-page', 'Body Sensation Meaning Check Page', 'cbt'::resource_kind, 'A page comparing the scary meaning a client gives a body sensation with other possible meanings.', 'Use it to help a client test alarming interpretations of body sensations.', array['Adults']::text[], '25 minutes', 'Ask the client to name a sensation, their prediction and alternatives. Medical questions belong with their physician, so encourage a check-up if they have not had one. Pair it with a gentle practice.', '[{"id": "f0", "type": "textarea", "label": "A sensation I notice:"}, {"id": "f1", "type": "textarea", "label": "The scary meaning I give it:"}, {"id": "f2", "type": "textarea", "label": "Other things it could mean:"}, {"id": "f3", "type": "textarea", "label": "What I could try to find out more:"}]'::jsonb, array['panic attacks', 'interoception', 'interpretation']::text[], '2026-10-31T15:00:00+00:00'::timestamptz),
  ('making-room-for-a-racing-heart-page', 'Making Room for a Racing Heart Page', 'act'::resource_kind, 'A page for allowing a racing heart or other sensations to be present while moving toward what matters.', 'Use it to help a client carry sensations along instead of fighting them.', array['Adults']::text[], '20 minutes', 'Practice making room for a mild sensation first, such as a held breath. Ask what the struggle costs and what they would do if the sensations were allowed to be there. Plan a values step.', '[{"id": "f0", "type": "textarea", "label": "A sensation I try to push away:"}, {"id": "f1", "type": "textarea", "label": "What the struggle costs me:"}, {"id": "f2", "type": "textarea", "label": "What I would do if I made room for it:"}, {"id": "f3", "type": "textarea", "label": "A step I will take this week:"}]'::jsonb, array['panic attacks', 'struggle switch', 'acceptance']::text[], '2026-10-31T15:00:00+00:00'::timestamptz),
  ('panic-peak-skills-card', 'Panic Peak Skills Card', 'dbt'::resource_kind, 'A pocket card pairing quick body skills and a self-statement for the peak of a panic wave.', 'Use it to help a client have a few steps ready for when panic peaks.', array['Adults', 'Teens']::text[], '20 minutes', 'Try each skill in session and let the client pick the ones that help. Cold-water or intense exercise steps should be skipped if there is a medical reason; check first. Rehearse the card when calm.', '[{"id": "f0", "type": "textarea", "label": "Skill one that helps me:"}, {"id": "f1", "type": "textarea", "label": "Skill two that helps me:"}, {"id": "f2", "type": "textarea", "label": "A sentence I can tell myself at the peak:"}, {"id": "f3", "type": "textarea", "label": "Where I keep the card:"}]'::jsonb, array['panic attacks', 'TIPP', 'distress tolerance']::text[], '2026-10-31T15:00:00+00:00'::timestamptz),
  ('sensation-detective-practice-game', 'Sensation Detective Practice Game', 'game'::resource_kind, 'A game of safely bringing on mild sensations, like spinning in a chair, and rating them.', 'Use it to help a group practice noticing mild sensations without alarm.', array['Teens', 'Adults', 'Groups']::text[], '20 minutes', 'Take turns trying a safe, brief exercise, such as breathing quickly for thirty seconds, and rate it. Rules: anyone can stop or pass at any time, and anyone with a medical reason can skip. Debrief on what they noticed.', '[{"id": "f0", "type": "textarea", "label": "An exercise I tried and what I felt:"}, {"id": "f1", "type": "textarea", "label": "My rating from zero to ten:"}, {"id": "f2", "type": "textarea", "label": "What I told myself:"}, {"id": "f3", "type": "textarea", "label": "What I learned from the game:"}]'::jsonb, array['panic attacks', 'interoceptive exposure', 'game']::text[], '2026-10-31T15:00:00+00:00'::timestamptz),
  ('family-routine-visual-schedule-page', 'Family Routine Visual Schedule Page', 'worksheet'::resource_kind, 'A page for building a simple picture schedule for mornings or evenings at home.', 'Use it to help a parent plan a steady routine a child can follow.', array['Adults']::text[], '25 minutes', 'Pick one routine, often mornings, and draw or list steps with the child in mind. Keep it to five steps at most. Review what works and what gets stuck after a week.', '[{"id": "f0", "type": "textarea", "label": "The routine I want to make easier:"}, {"id": "f1", "type": "textarea", "label": "The steps, in order:"}, {"id": "f2", "type": "textarea", "label": "What gets stuck:"}, {"id": "f3", "type": "textarea", "label": "How I will involve my child:"}]'::jsonb, array['parenting', 'routine', 'family']::text[], '2026-10-31T15:00:00+00:00'::timestamptz),
  ('parent-harsh-thought-catch-page', 'Parent Harsh Thought Catch Page', 'cbt'::resource_kind, 'A page for catching a harsh thought about a child or oneself during a hard moment.', 'Use it to help a parent notice and soften thoughts that fuel harsh reactions.', array['Adults']::text[], '20 minutes', 'Pick a recent moment and slow it down. Look for thoughts like he is doing this on purpose or I am failing. Draft a fairer version and rehearse it aloud.', '[{"id": "f0", "type": "textarea", "label": "The moment:"}, {"id": "f1", "type": "textarea", "label": "The thought I had:"}, {"id": "f2", "type": "textarea", "label": "How I reacted:"}, {"id": "f3", "type": "textarea", "label": "A fairer thought I could try:"}]'::jsonb, array['parenting', 'parent coaching', 'automatic thoughts']::text[], '2026-10-31T15:00:00+00:00'::timestamptz),
  ('co-parent-agreement-page', 'Co-Parent Agreement Page', 'couples'::resource_kind, 'A page for two parents to agree on a few shared rules and who handles what.', 'Use it to help co-parents decide on a few steady shared approaches.', array['Couples']::text[], '30 minutes', 'Keep it to three or four agreements. Each parent lists what matters most, and the page notes where they differ without trying to settle everything. Revisit after two weeks.', '[{"id": "f0", "type": "textarea", "label": "Parent A: what matters most to me:"}, {"id": "f1", "type": "textarea", "label": "Parent B: what matters most to me:"}, {"id": "f2", "type": "textarea", "label": "Where we already agree:"}, {"id": "f3", "type": "textarea", "label": "One agreement we will try this week:"}]'::jsonb, array['parenting', 'co-parenting', 'teamwork']::text[], '2026-10-31T15:00:00+00:00'::timestamptz),
  ('positive-family-rules-poster-craft', 'Positive Family Rules Poster Craft', 'kids'::resource_kind, 'A craft where a child and parent make a poster of a few positive family rules.', 'Use it to help a parent and child make clear, positive rules together.', array['Children']::text[], '30 minutes', 'Draw the rules together in positive words. Parent leads with what to do, not what not to do. Hang it somewhere visible and refer to it calmly.', '[{"id": "f0", "type": "textarea", "label": "Rules I like:"}, {"id": "f1", "type": "textarea", "label": "A rule I would add:"}, {"id": "f2", "type": "textarea", "label": "How my grown-up helps me remember:"}, {"id": "f3", "type": "textarea", "label": "What happens when we follow it:"}]'::jsonb, array['parenting', 'rules', 'craft', 'children']::text[], '2026-10-31T15:00:00+00:00'::timestamptz),
  ('specific-praise-practice-card-game', 'Specific Praise Practice Card Game', 'game'::resource_kind, 'A card game where parents practice labeled praise for effort and kind acts.', 'Use it to help parents practice specific praise in short bursts.', array['Adults', 'Groups']::text[], '20 minutes', 'Players draw a scenario and say a specific piece of praise. Rules: describe exactly what the child did and avoid but. Debrief on which praise sounded natural and which felt forced.', '[{"id": "f0", "type": "textarea", "label": "A scenario I drew:"}, {"id": "f1", "type": "textarea", "label": "The praise I gave:"}, {"id": "f2", "type": "textarea", "label": "What made it specific:"}, {"id": "f3", "type": "textarea", "label": "Where I will use it this week:"}]'::jsonb, array['parenting', 'praise', 'game']::text[], '2026-10-31T15:00:00+00:00'::timestamptz),
  ('postpartum-week-support-planner', 'Postpartum Week Support Planner', 'worksheet'::resource_kind, 'A weekly planner for who helps with meals, sleep and rest in the first weeks with a baby.', 'Use it to help a new parent line up concrete help for hard stretches.', array['Adults']::text[], '25 minutes', 'Have the client list what is hardest and who could take it on. Be specific about tasks and times. Expect difficulty asking for help and practice a short request together.', '[{"id": "f0", "type": "textarea", "label": "The hardest times of day for me:"}, {"id": "f1", "type": "textarea", "label": "People who could help and with what:"}, {"id": "f2", "type": "textarea", "label": "What I will ask for this week:"}, {"id": "f3", "type": "textarea", "label": "How I will rest when I can:"}]'::jsonb, array['perinatal and postpartum', 'support network', 'new parents']::text[], '2026-10-31T15:00:00+00:00'::timestamptz),
  ('new-parent-fair-thought-page', 'New Parent Fair Thought Page', 'cbt'::resource_kind, 'A page for answering thoughts about not being good enough as a new parent.', 'Use it to help a new parent respond to harsh thoughts about their parenting.', array['Adults']::text[], '20 minutes', 'Collect the thoughts and ask what they would say to a friend. Avoid arguing; look for a fair middle thought. Encourage them to mention persistent low mood to their care provider.', '[{"id": "f0", "type": "textarea", "label": "A harsh thought I had about myself as a parent:"}, {"id": "f1", "type": "textarea", "label": "What I would say to a friend:"}, {"id": "f2", "type": "textarea", "label": "What I have done well recently:"}, {"id": "f3", "type": "textarea", "label": "A fairer thought:"}]'::jsonb, array['perinatal and postpartum', 'self-criticism', 'balanced thinking']::text[], '2026-10-31T15:00:00+00:00'::timestamptz),
  ('values-in-the-newborn-blur-page', 'Values in the Newborn Blur Page', 'act'::resource_kind, 'A page for finding small values-based moments when days and nights run together.', 'Use it to help a new parent find meaning in small moments of care.', array['Adults']::text[], '20 minutes', 'Keep the page short enough for a tired person. Ask what matters about the kind of parent they want to be, and name tiny actions. Allow grief or ambivalence to be there.', '[{"id": "f0", "type": "textarea", "label": "What matters to me as a parent:"}, {"id": "f1", "type": "textarea", "label": "A small moment that showed it:"}, {"id": "f2", "type": "textarea", "label": "Something that is hard that I can allow:"}, {"id": "f3", "type": "textarea", "label": "A tiny action for tomorrow:"}]'::jsonb, array['perinatal and postpartum', 'values', 'meaning']::text[], '2026-10-31T15:00:00+00:00'::timestamptz),
  ('night-shift-fairness-conversation-page', 'Night Shift Fairness Conversation Page', 'couples'::resource_kind, 'A page for partners to talk about how night care, chores and rest are split.', 'Use it to help partners talk about the load and adjust it fairly.', array['Couples']::text[], '30 minutes', 'Each partner lists what they do, seen and unseen. Choose one change to try. Notice resentment and name it without blaming. Revisit in a week.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what I do that goes unseen:"}, {"id": "f1", "type": "textarea", "label": "Partner B: what I do that goes unseen:"}, {"id": "f2", "type": "textarea", "label": "What feels unfair right now:"}, {"id": "f3", "type": "textarea", "label": "One change we will try this week:"}]'::jsonb, array['perinatal and postpartum', 'mental load', 'household']::text[], '2026-10-31T15:00:00+00:00'::timestamptz),
  ('welcome-baby-sibling-story-craft', 'Welcome Baby Sibling Story Craft', 'kids'::resource_kind, 'A craft where an older child makes a book of what is staying the same and what is new.', 'Use it to help an older child talk about changes with a new baby.', array['Children']::text[], '30 minutes', 'The child draws pages such as things we still do together. The parent sets aside a short time each day just for the older child. Listen to mixed feelings without correcting them.', '[{"id": "f0", "type": "textarea", "label": "Something I still get to do:"}, {"id": "f1", "type": "textarea", "label": "Something that is new:"}, {"id": "f2", "type": "textarea", "label": "A feeling I have about the baby:"}, {"id": "f3", "type": "textarea", "label": "A special thing for me and my grown-up:"}]'::jsonb, array['perinatal and postpartum', 'sibling adjustment', 'craft', 'children']::text[], '2026-10-31T15:00:00+00:00'::timestamptz),
  ('inner-critic-versus-fair-friend-page', 'Inner Critic Versus Fair Friend Page', 'worksheet'::resource_kind, 'A two-voice page where a client writes what the critic says and what a fair friend would say.', 'Use it to help a client practice a fairer voice toward themselves.', array['Adults', 'Teens']::text[], '20 minutes', 'Let the client give the critic a name or a tone. Do not argue with it; ask what a fair friend would say instead. Practice reading the fair voice aloud and notice where it feels unbelievable.', '[{"id": "f0", "type": "textarea", "label": "What my critic says:"}, {"id": "f1", "type": "textarea", "label": "What it is trying to protect me from:"}, {"id": "f2", "type": "textarea", "label": "What a fair friend would say:"}, {"id": "f3", "type": "textarea", "label": "One sentence I can try this week:"}]'::jsonb, array['self-esteem', 'inner critic', 'self-compassion']::text[], '2026-10-31T15:00:00+00:00'::timestamptz),
  ('core-belief-evidence-notebook-page', 'Core Belief Evidence Notebook Page', 'cbt'::resource_kind, 'A page for collecting small pieces of evidence that nudge a harsh core belief.', 'Use it to help a client gather evidence that does not fit a harsh belief.', array['Adults']::text[], 'Ten minutes daily', 'Name one belief and rate how strongly it is held. Ask for one small observation a day that does not fit it. Review the notebook together and re-rate, expecting slow change.', '[{"id": "f0", "type": "textarea", "label": "The belief I am working on and how strongly I hold it:"}, {"id": "f1", "type": "textarea", "label": "Something today that does not fit it:"}, {"id": "f2", "type": "textarea", "label": "What that suggests about me:"}, {"id": "f3", "type": "textarea", "label": "How strongly I hold it now:"}]'::jsonb, array['self-esteem', 'core beliefs', 'evidence log']::text[], '2026-10-31T15:00:00+00:00'::timestamptz),
  ('worth-without-proving-it-page', 'Worth Without Proving It Page', 'act'::resource_kind, 'A page for dropping the need to prove worth and choosing values-based action anyway.', 'Use it to help a client act on values without waiting to feel worthy.', array['Adults']::text[], '25 minutes', 'Ask what the client is trying to prove and to whom. Explore what they would do if worth were not up for a vote. Choose one action to take for its own sake.', '[{"id": "f0", "type": "textarea", "label": "What I feel I have to prove:"}, {"id": "f1", "type": "textarea", "label": "Who I am trying to prove it to:"}, {"id": "f2", "type": "textarea", "label": "What I would do if I did not have to:"}, {"id": "f3", "type": "textarea", "label": "A step I will take just because it matters:"}]'::jsonb, array['self-esteem', 'self-worth', 'values', 'defusion']::text[], '2026-10-31T15:00:00+00:00'::timestamptz),
  ('self-validation-statements-practice-sheet', 'Self-Validation Statements Practice Sheet', 'dbt'::resource_kind, 'A sheet for writing validating statements a client can use for their own feelings.', 'Use it to help a client build a habit of acknowledging their own experience.', array['Adults', 'Teens']::text[], '20 minutes', 'Start with a feeling that makes sense given what happened. Write three statements the client could believe, avoiding overly rosy ones. Practice saying one aloud in session.', '[{"id": "f0", "type": "textarea", "label": "A feeling I had recently:"}, {"id": "f1", "type": "textarea", "label": "Why it makes sense given what happened:"}, {"id": "f2", "type": "textarea", "label": "A validating sentence for myself:"}, {"id": "f3", "type": "textarea", "label": "When I will say it to myself:"}]'::jsonb, array['self-esteem', 'self-validation', 'validation']::text[], '2026-10-31T15:00:00+00:00'::timestamptz),
  ('all-about-me-strengths-poster-craft', 'All About Me Strengths Poster Craft', 'kids'::resource_kind, 'A poster craft where a child draws and writes things they like about themselves and what they do well.', 'Use it to help a child notice what they are good at and what makes them them.', array['Children']::text[], '30 minutes', 'Include kinds of strengths beyond school and looks. The parent adds one thing they love about the child. Hang it where the child can see it, and add to it over time.', '[{"id": "f0", "type": "textarea", "label": "Things I am good at:"}, {"id": "f1", "type": "textarea", "label": "Things I like about me:"}, {"id": "f2", "type": "textarea", "label": "Something someone said they like about me:"}, {"id": "f3", "type": "textarea", "label": "What I want to add soon:"}]'::jsonb, array['self-esteem', 'strengths', 'craft', 'children']::text[], '2026-10-31T15:00:00+00:00'::timestamptz),
  ('social-situation-predictions-and-outcomes-page', 'Social Situation Predictions and Outcomes Page', 'worksheet'::resource_kind, 'A page for writing what a client predicts will happen in a social moment and what did.', 'Use it to help a client compare predictions about social moments with outcomes.', array['Adults', 'Teens']::text[], '20 minutes', 'Have them write a prediction and a rating beforehand. Afterward record what actually happened without a verdict. Notice patterns such as predicting that others judge harshly.', '[{"id": "f0", "type": "textarea", "label": "The social situation coming up:"}, {"id": "f1", "type": "textarea", "label": "What I predict will happen:"}, {"id": "f2", "type": "textarea", "label": "What actually happened:"}, {"id": "f3", "type": "textarea", "label": "What I notice about the difference:"}]'::jsonb, array['social anxiety', 'predictions', 'post-event processing']::text[], '2026-10-31T15:00:00+00:00'::timestamptz),
  ('after-the-event-replay-reframe-page', 'After the Event Replay Reframe Page', 'cbt'::resource_kind, 'A page for catching the replay after a social event and answering it more fairly.', 'Use it to help a client respond to harsh replays after social events.', array['Adults']::text[], '20 minutes', 'Ask what the replay highlights and what it leaves out. Look for mind reading and ask for facts. Draft a kinder, more complete summary of the event.', '[{"id": "f0", "type": "textarea", "label": "The event I keep replaying:"}, {"id": "f1", "type": "textarea", "label": "The part my mind focuses on:"}, {"id": "f2", "type": "textarea", "label": "What it leaves out:"}, {"id": "f3", "type": "textarea", "label": "A fairer summary:"}]'::jsonb, array['social anxiety', 'post-event processing', 'mind reading']::text[], '2026-10-31T15:00:00+00:00'::timestamptz),
  ('social-courage-values-step-page', 'Social Courage Values Step Page', 'act'::resource_kind, 'A page connecting a social step to the value of closeness and choosing one small action.', 'Use it to help a client take a social step for the sake of what they value.', array['Adults']::text[], '25 minutes', 'Ask what they want from connection and choose one small step, such as a greeting. Name the discomfort they are willing to bring. Review what happened without scoring it.', '[{"id": "f0", "type": "textarea", "label": "What I want from connection:"}, {"id": "f1", "type": "textarea", "label": "A small social step:"}, {"id": "f2", "type": "textarea", "label": "Discomfort I am willing to bring:"}, {"id": "f3", "type": "textarea", "label": "How I will check in afterward:"}]'::jsonb, array['social anxiety', 'values', 'courage', 'social connection']::text[], '2026-10-31T15:00:00+00:00'::timestamptz),
  ('brave-hello-practice-puppets-craft', 'Brave Hello Practice Puppets Craft', 'kids'::resource_kind, 'A craft where a child makes puppets and practices saying hello and joining in.', 'Use it to help a child rehearse simple social steps through play.', array['Children']::text[], '30 minutes', 'Make puppets from socks and act out hello, asking to join and what to say if nobody answers. The parent plays a puppet too and cheers small efforts. Keep it playful.', '[{"id": "f0", "type": "textarea", "label": "My puppet says hello like this:"}, {"id": "f1", "type": "textarea", "label": "A way to join in at play:"}, {"id": "f2", "type": "textarea", "label": "What I can do if no one answers:"}, {"id": "f3", "type": "textarea", "label": "A brave hello I will try:"}]'::jsonb, array['social anxiety', 'social skills', 'craft', 'children']::text[], '2026-10-31T15:00:00+00:00'::timestamptz),
  ('small-talk-topic-spinner-game', 'Small Talk Topic Spinner Game', 'game'::resource_kind, 'A spinner game for taking turns with easy small-talk starters and follow-up questions.', 'Use it to help a group practice small talk in a safe setting.', array['Teens', 'Adults', 'Groups']::text[], '20 minutes', 'Players spin, ask the topic question and the next player replies and asks one follow-up. Rules: anyone may pass, and no one laughs at an answer. Debrief on what made it easier.', '[{"id": "f0", "type": "textarea", "label": "A topic I liked:"}, {"id": "f1", "type": "textarea", "label": "A follow-up question I asked:"}, {"id": "f2", "type": "textarea", "label": "What made it easier:"}, {"id": "f3", "type": "textarea", "label": "Where I could try small talk this week:"}]'::jsonb, array['social anxiety', 'small talk', 'game']::text[], '2026-10-31T15:00:00+00:00'::timestamptz),
  ('grief-waves-day-planner', 'Grief Waves Day Planner', 'worksheet'::resource_kind, 'A planner that expects waves of grief and sets aside places for comfort, tasks and rest.', 'Use it to help a client plan around grief instead of against it.', array['Adults']::text[], '20 minutes', 'Mark times of day or week that are harder. Plan one comfort and one small task. There is no right pace for grief, so avoid timelines.', '[{"id": "f0", "type": "textarea", "label": "Times that are hardest for me:"}, {"id": "f1", "type": "textarea", "label": "A comfort for those times:"}, {"id": "f2", "type": "textarea", "label": "A small task I can manage:"}, {"id": "f3", "type": "textarea", "label": "Who I can reach out to:"}]'::jsonb, array['grief and loss', 'pacing', 'support']::text[], '2026-10-31T15:00:00+00:00'::timestamptz),
  ('guilt-and-what-i-knew-then-page', 'Guilt and What I Knew Then Page', 'cbt'::resource_kind, 'A page for looking at guilt thoughts by what the client knew at the time.', 'Use it to help a client look at guilt with the facts they had then.', array['Adults']::text[], '25 minutes', 'Sit with the guilt before reframing it. Ask what they knew then and what a friend would say. Offer, do not impose, a fairer sentence.', '[{"id": "f0", "type": "textarea", "label": "The guilt thought:"}, {"id": "f1", "type": "textarea", "label": "What I knew at the time:"}, {"id": "f2", "type": "textarea", "label": "What a friend would say:"}, {"id": "f3", "type": "textarea", "label": "A sentence that feels fair:"}]'::jsonb, array['grief and loss', 'guilt', 'self-blame']::text[], '2026-10-31T15:00:00+00:00'::timestamptz),
  ('love-that-travels-with-me-page', 'Love That Travels With Me Page', 'act'::resource_kind, 'A page for naming what the client loved and one way to carry it into this week.', 'Use it to help a client connect loss to love and values.', array['Adults']::text[], '25 minutes', 'Let the client lead with memories if they wish. Link what they loved to a value and one small action this week. Pain and love are both allowed on the page.', '[{"id": "f0", "type": "textarea", "label": "What I loved about them:"}, {"id": "f1", "type": "textarea", "label": "A value that comes from that love:"}, {"id": "f2", "type": "textarea", "label": "One way to carry it this week:"}, {"id": "f3", "type": "textarea", "label": "What I am willing to feel as I do:"}]'::jsonb, array['grief and loss', 'continuing bonds', 'values']::text[], '2026-10-31T15:00:00+00:00'::timestamptz),
  ('different-grief-styles-partner-talk-guide', 'Different Grief Styles Partner Talk Guide', 'couples'::resource_kind, 'A guide for partners who grieve differently to share what each needs.', 'Use it to help partners understand each other''s different ways of grieving.', array['Couples']::text[], '30 minutes', 'Each partner describes how they grieve and what they need. Listen without comparing. End with one thing each can do for the other.', '[{"id": "f0", "type": "textarea", "label": "Partner A: how I grieve:"}, {"id": "f1", "type": "textarea", "label": "Partner A: what I need from my partner:"}, {"id": "f2", "type": "textarea", "label": "Partner B: how I grieve:"}, {"id": "f3", "type": "textarea", "label": "Partner B: what I need from my partner:"}]'::jsonb, array['grief and loss', 'bereavement', 'support']::text[], '2026-10-31T15:00:00+00:00'::timestamptz),
  ('keepsake-box-decorating-craft', 'Keepsake Box Decorating Craft', 'kids'::resource_kind, 'A craft where a child decorates a box for drawings and keepsakes of someone they miss.', 'Use it to help a child hold memories of someone who has died.', array['Children']::text[], '30 minutes', 'The child decorates a box and fills it with drawings or small items. The parent shares a memory too. Use words about death that the family uses and let the child lead.', '[{"id": "f0", "type": "textarea", "label": "Who this box is for:"}, {"id": "f1", "type": "textarea", "label": "Something I remember:"}, {"id": "f2", "type": "textarea", "label": "Something I want to put inside:"}, {"id": "f3", "type": "textarea", "label": "Who I can talk to when I miss them:"}]'::jsonb, array['grief and loss', 'memories', 'craft', 'children']::text[], '2026-10-31T15:00:00+00:00'::timestamptz),
  ('needs-and-requests-translation-page', 'Needs and Requests Translation Page', 'worksheet'::resource_kind, 'A page that turns a complaint into a need and a specific request.', 'Use it to help a client turn complaints into clear requests.', array['Adults']::text[], '20 minutes', 'Choose a complaint, name the need under it and rewrite it as a request that is specific and doable. Practice saying it aloud. Requests can be declined.', '[{"id": "f0", "type": "textarea", "label": "My complaint:"}, {"id": "f1", "type": "textarea", "label": "The need under it:"}, {"id": "f2", "type": "textarea", "label": "A request that is specific:"}, {"id": "f3", "type": "textarea", "label": "How I will say it:"}]'::jsonb, array['relationship issues', 'needs', 'communication']::text[], '2026-10-31T15:00:00+00:00'::timestamptz),
  ('story-check-during-conflict-page', 'Story Check During Conflict Page', 'cbt'::resource_kind, 'A page for checking the story a client tells about a partner''s behavior.', 'Use it to help a client test their interpretation of a hurtful moment.', array['Adults']::text[], '20 minutes', 'Separate what happened from the story. List other possible reasons and a question to ask. The goal is curiosity, not excusing hurt.', '[{"id": "f0", "type": "textarea", "label": "What happened, only the facts:"}, {"id": "f1", "type": "textarea", "label": "The story I told myself:"}, {"id": "f2", "type": "textarea", "label": "Other possible reasons:"}, {"id": "f3", "type": "textarea", "label": "A question I could ask:"}]'::jsonb, array['relationship issues', 'assumptions', 'interpretation']::text[], '2026-10-31T15:00:00+00:00'::timestamptz),
  ('partner-i-want-to-be-values-page', 'Partner I Want to Be Values Page', 'act'::resource_kind, 'A page for naming the partner a client wants to be and one action to match.', 'Use it to help a client act on values within a relationship.', array['Adults']::text[], '25 minutes', 'Ask who they want to be in the relationship, whatever the other person does. Pick one action within their control. Respect their right to decide about the relationship.', '[{"id": "f0", "type": "textarea", "label": "The kind of partner or friend I want to be:"}, {"id": "f1", "type": "textarea", "label": "A recent moment I acted like that:"}, {"id": "f2", "type": "textarea", "label": "An action in my control this week:"}, {"id": "f3", "type": "textarea", "label": "What might get in the way:"}]'::jsonb, array['relationship issues', 'values', 'relationships']::text[], '2026-10-31T15:00:00+00:00'::timestamptz),
  ('small-bids-and-responses-weekly-tracker', 'Small Bids and Responses Weekly Tracker', 'couples'::resource_kind, 'A tracker for partners to note small bids for attention and how each was met.', 'Use it to help partners notice small moments of connection.', array['Couples']::text[], 'One week', 'Define a bid with examples. Each partner tallies bids and responses over a week. Review without blame and choose one bid to answer more often.', '[{"id": "f0", "type": "textarea", "label": "Partner A: bids I noticed from my partner:"}, {"id": "f1", "type": "textarea", "label": "Partner A: bids I made:"}, {"id": "f2", "type": "textarea", "label": "Partner B: bids I noticed from my partner:"}, {"id": "f3", "type": "textarea", "label": "Partner B: bids I made:"}]'::jsonb, array['relationship issues', 'bids', 'Gottman']::text[], '2026-10-31T15:00:00+00:00'::timestamptz),
  ('conversation-cards-turn-taking-game', 'Conversation Cards Turn-Taking Game', 'game'::resource_kind, 'A card game where players take turns asking and listening to deepen conversation.', 'Use it to help a pair or group practice asking and listening.', array['Adults', 'Couples', 'Groups']::text[], '20 minutes', 'Each player answers a card and the next reflects back before answering. Rules: a pass is allowed and no interruptions. Debrief on what it felt like to be heard.', '[{"id": "f0", "type": "textarea", "label": "A question I liked:"}, {"id": "f1", "type": "textarea", "label": "What I heard from someone else:"}, {"id": "f2", "type": "textarea", "label": "How it felt to be listened to:"}, {"id": "f3", "type": "textarea", "label": "A question I want to ask someone I know:"}]'::jsonb, array['relationship issues', 'listening', 'conversation', 'game']::text[], '2026-10-31T15:00:00+00:00'::timestamptz),
  ('safety-and-pacing-choice-card', 'Safety and Pacing Choice Card', 'worksheet'::resource_kind, 'A card where a client sets their own pace for sessions and names what helps them feel in control.', 'Use it to help a client keep control over the pace and shape of the work.', array['Adults', 'Teens']::text[], '20 minutes', 'The card is about choices in the room, never about events. Offer options such as stop signals, breaks and seating. Revisit at the start of sessions, and respect each change.', '[{"id": "f0", "type": "textarea", "label": "A signal I can use to pause or stop:"}, {"id": "f1", "type": "textarea", "label": "What helps me feel in control of the session:"}, {"id": "f2", "type": "textarea", "label": "What I want my therapist to know about pacing:"}, {"id": "f3", "type": "textarea", "label": "A support I can lean on between sessions:"}]'::jsonb, array['sexual abuse', 'safety', 'pacing', 'stabilizing']::text[], '2026-10-31T15:00:00+00:00'::timestamptz),
  ('safe-now-self-talk-cards', 'Safe Now Self-Talk Cards', 'cbt'::resource_kind, 'A set of cards with present-focused statements a client writes in their own words.', 'Use it to help a client build present-focused statements for hard moments.', array['Adults']::text[], '20 minutes', 'Write only about the present and what is true now. Do not ask for any account of the past. Test the cards in session and revise any that do not ring true.', '[{"id": "f0", "type": "textarea", "label": "Where I am right now:"}, {"id": "f1", "type": "textarea", "label": "Who and what keeps me safe now:"}, {"id": "f2", "type": "textarea", "label": "A sentence that is true and helps:"}, {"id": "f3", "type": "textarea", "label": "Where I will keep these cards:"}]'::jsonb, array['sexual abuse', 'safety', 'self-talk', 'stabilizing']::text[], '2026-10-31T15:00:00+00:00'::timestamptz),
  ('values-and-support-compass-page', 'Values and Support Compass Page', 'act'::resource_kind, 'A page for naming values and the people or places that support moving toward them.', 'Use it to help a client link values to supports they can use.', array['Adults']::text[], '25 minutes', 'Stay with present values and supports. The client decides how much to share, and a pass is always fine. Ask who they trust and what small step they could take with that person.', '[{"id": "f0", "type": "textarea", "label": "What matters to me in my life now:"}, {"id": "f1", "type": "textarea", "label": "People or places that support me:"}, {"id": "f2", "type": "textarea", "label": "A small step I can take:"}, {"id": "f3", "type": "textarea", "label": "How I will take care of myself afterward:"}]'::jsonb, array['sexual abuse', 'values', 'support', 'pacing']::text[], '2026-10-31T15:00:00+00:00'::timestamptz),
  ('grounding-with-the-five-senses-skills-page', 'Grounding With the Five Senses Skills Page', 'dbt'::resource_kind, 'A skills page listing five-senses grounding steps a client tests and rates.', 'Use it to help a client find grounding steps that work for them.', array['Adults', 'Teens']::text[], '20 minutes', 'Try steps in session and rate each from zero to ten. Some senses may be unwelcome, so ask and let the client lead. Keep content about the present only.', '[{"id": "f0", "type": "textarea", "label": "A sight that grounds me:"}, {"id": "f1", "type": "textarea", "label": "A sound that grounds me:"}, {"id": "f2", "type": "textarea", "label": "A touch or smell that grounds me:"}, {"id": "f3", "type": "textarea", "label": "The step I rate highest:"}]'::jsonb, array['sexual abuse', 'grounding', 'distress tolerance', 'stabilizing']::text[], '2026-10-31T15:00:00+00:00'::timestamptz),
  ('my-body-is-mine-safe-helpers-craft', 'My Body Is Mine Safe Helpers Craft', 'kids'::resource_kind, 'A craft where a child draws their safe helpers and learns that their body belongs to them.', 'Use it to help a child learn body safety and name trusted helpers.', array['Children']::text[], '30 minutes', 'Keep to body safety rules, such as private parts and telling a safe adult. The child draws helpers and a parent learns who is on the list. You have reporting duties if a child discloses; listen calmly, do not probe or promise secrecy.', '[{"id": "f0", "type": "textarea", "label": "Grown-ups I can tell if something feels wrong:"}, {"id": "f1", "type": "textarea", "label": "What I can say or do if I feel unsafe:"}, {"id": "f2", "type": "textarea", "label": "Why my body belongs to me:"}, {"id": "f3", "type": "textarea", "label": "Where I will put my helper list:"}]'::jsonb, array['sexual abuse', 'body safety', 'safe adults', 'children']::text[], '2026-10-31T15:00:00+00:00'::timestamptz),
  ('coping-skills-by-situation-menu', 'Coping Skills by Situation Menu', 'worksheet'::resource_kind, 'A menu matching coping skills with situations such as before bed, at work or after an argument.', 'Use it to help a client choose a coping skill that fits the situation.', array['Adults', 'Teens']::text[], '25 minutes', 'Have the client list three tough situations and one skill for each. Test a skill in session. Ask where each skill would be hard to use and adjust.', '[{"id": "f0", "type": "textarea", "label": "A tough situation I face:"}, {"id": "f1", "type": "textarea", "label": "A skill that suits it:"}, {"id": "f2", "type": "textarea", "label": "Where it might be hard to use:"}, {"id": "f3", "type": "textarea", "label": "A backup skill:"}]'::jsonb, array['coping skills', 'coping skills planning', 'menu']::text[], '2026-10-31T15:00:00+00:00'::timestamptz),
  ('coping-thoughts-index-card-set', 'Coping Thoughts Index Card Set', 'cbt'::resource_kind, 'A set of index cards with realistic coping statements the client picks and rehearses.', 'Use it to help a client carry realistic coping statements for hard moments.', array['Adults']::text[], '20 minutes', 'Write statements the client believes, such as this is hard and I can ride it out. Avoid cheerleading lines. Rehearse using them in a mild moment.', '[{"id": "f0", "type": "textarea", "label": "A hard moment I expect:"}, {"id": "f1", "type": "textarea", "label": "A realistic statement for it:"}, {"id": "f2", "type": "textarea", "label": "A second statement:"}, {"id": "f3", "type": "textarea", "label": "When I will read the cards:"}]'::jsonb, array['coping skills', 'coping thoughts', 'cue cards']::text[], '2026-10-31T15:00:00+00:00'::timestamptz),
  ('willing-to-feel-it-coping-page', 'Willing to Feel It Coping Page', 'act'::resource_kind, 'A page for choosing to move through discomfort with a skill in hand.', 'Use it to help a client pair willingness with a coping step.', array['Adults']::text[], '20 minutes', 'Separate skills that help you move toward values from those that only avoid. Ask which use applies. Neither is wrong; the aim is flexibility.', '[{"id": "f0", "type": "textarea", "label": "A discomfort I often avoid:"}, {"id": "f1", "type": "textarea", "label": "A skill that helps me stay in the moment:"}, {"id": "f2", "type": "textarea", "label": "What I am moving toward:"}, {"id": "f3", "type": "textarea", "label": "How I will use the skill this week:"}]'::jsonb, array['coping skills', 'willingness', 'skills']::text[], '2026-10-31T15:00:00+00:00'::timestamptz),
  ('self-soothe-kit-builder-page', 'Self-Soothe Kit Builder Page', 'dbt'::resource_kind, 'A page for building a kit of items that soothe each of the five senses.', 'Use it to help a client assemble a small kit of soothing items.', array['Adults', 'Teens']::text[], '25 minutes', 'Plan one item per sense and gather the items. Remind clients that a kit is for comfort, not avoidance. Revisit what to add or remove.', '[{"id": "f0", "type": "textarea", "label": "Something to see:"}, {"id": "f1", "type": "textarea", "label": "Something to hear:"}, {"id": "f2", "type": "textarea", "label": "Something to touch, smell or taste:"}, {"id": "f3", "type": "textarea", "label": "Where I will keep my kit:"}]'::jsonb, array['coping skills', 'self-soothe', 'toolbox']::text[], '2026-10-31T15:00:00+00:00'::timestamptz),
  ('coping-skills-charades-game', 'Coping Skills Charades Game', 'game'::resource_kind, 'A charades game where players act out a coping skill and others guess it.', 'Use it to help a group learn and remember coping skills through play.', array['Children', 'Teens', 'Groups']::text[], '20 minutes', 'Players draw a skill card and act it without words while the others guess. Rules: no touching others, pass allowed. Debrief on which skills they want to add to their own list.', '[{"id": "f0", "type": "textarea", "label": "A skill I acted out:"}, {"id": "f1", "type": "textarea", "label": "A skill I guessed:"}, {"id": "f2", "type": "textarea", "label": "A skill I want to try:"}, {"id": "f3", "type": "textarea", "label": "When I would use it:"}]'::jsonb, array['coping skills', 'skills', 'charades', 'game']::text[], '2026-10-31T15:00:00+00:00'::timestamptz),
  ('fear-ladder-building-page', 'Fear Ladder Building Page', 'worksheet'::resource_kind, 'A page for listing small steps toward a feared situation and rating each one.', 'Use it to help a client build a gradual set of steps toward a feared situation.', array['Adults', 'Teens']::text[], '30 minutes', 'Have the client write ten steps and rate each from zero to ten. Fill the gaps so steps are about two points apart. The client chooses the pace and the first step.', '[{"id": "f0", "type": "textarea", "label": "The situation I avoid:"}, {"id": "f1", "type": "textarea", "label": "Steps from easiest to hardest, with ratings:"}, {"id": "f2", "type": "textarea", "label": "Where I might start:"}, {"id": "f3", "type": "textarea", "label": "What I will do to support myself:"}]'::jsonb, array['phobias', 'fear ladder', 'hierarchy', 'exposure']::text[], '2026-10-31T15:00:00+00:00'::timestamptz),
  ('feared-outcome-probability-check-page', 'Feared Outcome Probability Check Page', 'cbt'::resource_kind, 'A page for writing the feared outcome and checking what has happened in the past.', 'Use it to help a client compare feared outcomes with real past experience.', array['Adults']::text[], '20 minutes', 'Ask what the client fears will happen and what has actually happened before. Avoid forcing reassurance. Use their own history as the evidence.', '[{"id": "f0", "type": "textarea", "label": "What I fear will happen:"}, {"id": "f1", "type": "textarea", "label": "What has happened in the past:"}, {"id": "f2", "type": "textarea", "label": "What I could do if it did happen:"}, {"id": "f3", "type": "textarea", "label": "A more complete thought:"}]'::jsonb, array['phobias', 'predictions', 'fear']::text[], '2026-10-31T15:00:00+00:00'::timestamptz),
  ('what-fear-costs-me-crossroads-page', 'What Fear Costs Me Crossroads Page', 'act'::resource_kind, 'A page for seeing what a fear has taken from a client and what they would choose to do.', 'Use it to help a client see what avoidance costs against what they value.', array['Adults']::text[], '25 minutes', 'Explore what the fear has cost and what the client would want back. Choose one small step to move toward it. Honor their pace.', '[{"id": "f0", "type": "textarea", "label": "What the fear keeps me from:"}, {"id": "f1", "type": "textarea", "label": "What I would want to do again:"}, {"id": "f2", "type": "textarea", "label": "A small step in that direction:"}, {"id": "f3", "type": "textarea", "label": "What I am willing to feel to take it:"}]'::jsonb, array['phobias', 'values', 'avoidance', 'approach']::text[], '2026-10-31T15:00:00+00:00'::timestamptz),
  ('fear-fighter-step-poster-craft', 'Fear Fighter Step Poster Craft', 'kids'::resource_kind, 'A craft where a child makes a poster of small steps toward something they fear and stickers each one.', 'Use it to help a child take small brave steps toward a fear.', array['Children']::text[], '30 minutes', 'Draw a path of small steps and let the child choose the first. The parent stays calm, cheers effort and does not force a step. Go at the child pace.', '[{"id": "f0", "type": "textarea", "label": "Something I am scared of:"}, {"id": "f1", "type": "textarea", "label": "Small steps from easy to hard:"}, {"id": "f2", "type": "textarea", "label": "My first step:"}, {"id": "f3", "type": "textarea", "label": "Who helps me:"}]'::jsonb, array['phobias', 'fear ladder', 'craft', 'children']::text[], '2026-10-31T15:00:00+00:00'::timestamptz),
  ('roll-a-brave-step-dice-game', 'Roll a Brave Step Dice Game', 'game'::resource_kind, 'A dice game where each roll picks a small brave step from a card the group wrote.', 'Use it to help a group practice small approach steps in a playful setting.', array['Teens', 'Adults', 'Groups']::text[], '20 minutes', 'Players write small steps, such as looking at a picture, and roll a die to choose a card. Rules: anyone can pass or choose an easier card. Debrief on how it felt to try.', '[{"id": "f0", "type": "textarea", "label": "A step I tried:"}, {"id": "f1", "type": "textarea", "label": "How scary it felt before and after:"}, {"id": "f2", "type": "textarea", "label": "What I told myself:"}, {"id": "f3", "type": "textarea", "label": "A step I want to try next:"}]'::jsonb, array['phobias', 'exposure', 'approach', 'game']::text[], '2026-10-31T15:00:00+00:00'::timestamptz),
  ('what-my-body-does-for-me-page', 'What My Body Does For Me Page', 'worksheet'::resource_kind, 'A page listing what the body lets a client do and experience each day.', 'Use it to help a client notice what their body does for them.', array['Adults', 'Teens']::text[], '20 minutes', 'Focus on functions and experiences such as hugging or walking. Avoid appearance entirely. If the client slips into critique, redirect to what the body does.', '[{"id": "f0", "type": "textarea", "label": "Things my body lets me do:"}, {"id": "f1", "type": "textarea", "label": "Experiences I enjoy through my body:"}, {"id": "f2", "type": "textarea", "label": "A time I was glad of what it did:"}, {"id": "f3", "type": "textarea", "label": "How I want to thank it:"}]'::jsonb, array['body image', 'body', 'gratitude', 'appreciation']::text[], '2026-10-31T15:00:00+00:00'::timestamptz),
  ('mirror-and-media-thought-check-page', 'Mirror and Media Thought Check Page', 'cbt'::resource_kind, 'A page for catching thoughts that come up around mirrors and media and answering them.', 'Use it to help a client respond to critical thoughts triggered by mirrors and media.', array['Adults', 'Teens']::text[], '25 minutes', 'Capture the trigger, the thought and the feeling. Ask what the thought assumes and what a friend would say. Draft a more balanced thought, and a different thing to do.', '[{"id": "f0", "type": "textarea", "label": "The trigger:"}, {"id": "f1", "type": "textarea", "label": "The thought:"}, {"id": "f2", "type": "textarea", "label": "What it assumes:"}, {"id": "f3", "type": "textarea", "label": "A more balanced thought:"}]'::jsonb, array['body image', 'social comparison', 'media', 'thought challenging']::text[], '2026-10-31T15:00:00+00:00'::timestamptz),
  ('living-fully-beyond-appearance-values-page', 'Living Fully Beyond Appearance Values Page', 'act'::resource_kind, 'A page for naming what a client would do if appearance thoughts did not decide their day.', 'Use it to help a client act on values while critical thoughts are present.', array['Adults']::text[], '25 minutes', 'Ask what the client has been holding back on and what they would do. Choose one small action. Thoughts about appearance may stay, and that is okay.', '[{"id": "f0", "type": "textarea", "label": "What I hold back on:"}, {"id": "f1", "type": "textarea", "label": "What I would do instead:"}, {"id": "f2", "type": "textarea", "label": "What my mind says when I think of it:"}, {"id": "f3", "type": "textarea", "label": "A step I will take this week:"}]'::jsonb, array['body image', 'values', 'self-acceptance', 'defusion']::text[], '2026-10-31T15:00:00+00:00'::timestamptz),
  ('things-i-like-about-me-mirror-craft', 'Things I Like About Me Mirror Craft', 'kids'::resource_kind, 'A craft where a child decorates a mirror frame with words about what they do and are, not how they look.', 'Use it to help a child notice qualities beyond looks.', array['Children']::text[], '25 minutes', 'Decorate a paper frame with words such as kind, funny and strong. The parent adds one quality too. Keep the focus on actions and character.', '[{"id": "f0", "type": "textarea", "label": "Kind things about me:"}, {"id": "f1", "type": "textarea", "label": "Things I do well:"}, {"id": "f2", "type": "textarea", "label": "What my grown-up loves about me:"}, {"id": "f3", "type": "textarea", "label": "A word I will add to my frame:"}]'::jsonb, array['body image', 'self-esteem', 'craft', 'children']::text[], '2026-10-31T15:00:00+00:00'::timestamptz),
  ('compliment-beyond-looks-card-game', 'Compliment Beyond Looks Card Game', 'game'::resource_kind, 'A card game where players give and receive compliments about skills and character.', 'Use it to help a group give and receive non-appearance compliments.', array['Teens', 'Adults', 'Groups']::text[], '20 minutes', 'Players draw a card with a prompt and compliment someone on a quality or action. Rules: never about looks, and anyone may pass. Debrief on how it felt to receive one.', '[{"id": "f0", "type": "textarea", "label": "A compliment I gave:"}, {"id": "f1", "type": "textarea", "label": "A compliment I received:"}, {"id": "f2", "type": "textarea", "label": "How it felt:"}, {"id": "f3", "type": "textarea", "label": "A quality I like in myself:"}]'::jsonb, array['body image', 'compliments', 'game']::text[], '2026-10-31T15:00:00+00:00'::timestamptz)
